import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test successful user registration with valid email format, proper password
 * requirements, and complete session context. Validates email uniqueness
 * functionality, password hashing verification, immediate account activation,
 * and JWT token generation. Ensures proper handling of optional name field, IP
 * address tracking, and referral source monitoring. Tests complete registration
 * workflow with immediate authentication capability.
 */
export async function test_api_auth_user_registration_email_verification_success(
  connection: api.IConnection,
) {
  // Step 1: Generate test data for user registration
  const testEmail = typia.random<string & tags.Format<"email">>();
  const testPassword = RandomGenerator.alphaNumeric(12); // Secure random password
  const testName = RandomGenerator.name();
  const testIp = typia.random<string & tags.Format<"ipv4">>();
  const testHref = "https://example.com/app/signup";
  const testReferrer = "https://example.com";

  // Step 2: Create registration request with valid data
  const registrationData = {
    email: testEmail,
    password: testPassword,
    name: testName,
    ip: testIp,
    href: testHref,
    referrer: testReferrer,
  } satisfies ITodoAppUser.ICreate;

  // Step 3: Execute user registration
  const createdUser = await api.functional.auth.user.join(connection, {
    body: registrationData,
  });
  typia.assert(createdUser);

  // Step 4: Validate JWT token generation
  TestValidator.predicate(
    "JWT access token should be generated",
    createdUser.token.access.length > 0,
  );
  TestValidator.predicate(
    "JWT refresh token should be generated",
    createdUser.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "Token expiration should be set",
    createdUser.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "Refresh token expiration should be set",
    createdUser.token.refreshable_until.length > 0,
  );

  // Step 5: Validate user account properties
  TestValidator.equals(
    "Email should match registration input",
    createdUser.email,
    testEmail,
  );
  TestValidator.equals(
    "Name should match registration input",
    createdUser.name,
    testName,
  );
  TestValidator.equals(
    "User status should be active",
    createdUser.status,
    "active",
  );
  TestValidator.predicate(
    "Created_at timestamp should be present",
    createdUser.created_at.length > 0,
  );
  TestValidator.predicate(
    "Updated_at timestamp should be present",
    createdUser.updated_at.length > 0,
  );

  // Step 6: Validate account activation (no deleted_at for active accounts)
  TestValidator.equals(
    "Deleted_at should be null for active accounts",
    createdUser.deleted_at,
    null,
  );

  // Step 7: Test email uniqueness by attempting duplicate registration
  await TestValidator.error(
    "Duplicate email registration should fail",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          ...registrationData,
          name: RandomGenerator.name(), // Different name
        } satisfies ITodoAppUser.ICreate,
      });
    },
  );

  // Step 8: Test with null name (optional field)
  const anonymousUser = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      href: testHref,
      referrer: testReferrer,
      // name field omitted to test null handling
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(anonymousUser);

  TestValidator.equals(
    "Name can be null when not provided",
    anonymousUser.name,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test email uniqueness validation rejection when attempting to register with
 * an existing email address.
 *
 * This test validates the critical security feature that prevents duplicate
 * email registrations in the system. The test ensures that when a user attempts
 * to create an account with an email that already exists in the database, the
 * system properly rejects the request and provides appropriate error feedback.
 *
 * Testing steps:
 *
 * 1. Generate random test data for user registration
 * 2. Create initial user account with unique email
 * 3. Verify successful account creation with proper API response
 * 4. Attempt duplicate registration with same email address
 * 5. Validate error handling and rejection behavior
 * 6. Confirm original account remains unaffected
 *
 * This test is essential for preventing duplicate accounts, maintaining data
 * integrity, and ensuring appropriate user feedback during registration
 * failures.
 */
export async function test_api_auth_user_registration_email_duplicate_prevention(
  connection: api.IConnection,
) {
  // Step 1: Generate unique test data
  const testEmail = typia.random<string & tags.Format<"email">>();
  const testPassword = "SecureValidPassword123";
  const testName = RandomGenerator.name();
  const testHref = `http://localhost:3000/register`;
  const testReferrer = `http://localhost:3000/signup`;

  // Step 2: Create initial user account successfully
  const firstUser = await api.functional.auth.user.join(connection, {
    body: {
      email: testEmail,
      password: testPassword,
      name: testName,
      href: testHref,
      referrer: testReferrer,
    } satisfies ITodoAppUser.ICreate,
  });

  // Verify first registration succeeded
  typia.assert(firstUser);
  TestValidator.equals("first user has email", firstUser.email, testEmail);
  TestValidator.predicate("first user has valid ID", firstUser.id.length > 0);

  // Step 3: Attempt duplicate registration with same email
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: {
          email: testEmail, // Same email as first user
          password: testPassword,
          name: testName,
          href: testHref,
          referrer: testReferrer,
        } satisfies ITodoAppUser.ICreate,
      });
    },
  );

  // Step 4: Verify alternative registration still works
  const alternativeEmail = typia.random<string & tags.Format<"email">>();
  const alternativeUser = await api.functional.auth.user.join(connection, {
    body: {
      email: alternativeEmail,
      password: testPassword,
      name: testName,
      href: testHref,
      referrer: testReferrer,
    } satisfies ITodoAppUser.ICreate,
  });

  typia.assert(alternativeUser);
  TestValidator.notEquals(
    "alternative user has different email",
    alternativeUser.email,
    testEmail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test password validation functionality during user registration, focusing on
 * rejection of weak passwords.
 *
 * This test validates that the API properly rejects passwords that don't meet
 * security requirements, specifically testing minimum length constraints and
 * ensuring proper error handling for insufficient password strength. The test
 * scenarios include:
 *
 * 1. Attempt registration with a password that's too short (below minimum
 *    requirements)
 * 2. Verify the API rejects the weak password with appropriate error handling
 * 3. Demonstrate that valid passwords are accepted when other requirements are met
 * 4. Test edge cases around password length boundaries
 *
 * The test focuses on business logic validation rather than type checking,
 * ensuring the password validation system enforces modern security standards
 * while providing clear guidance to users.
 */
export async function test_api_auth_user_registration_weak_password_rejection(
  connection: api.IConnection,
) {
  // Generate valid email and other required fields
  const validEmail = typia.random<string & tags.Format<"email">>();
  const validName = RandomGenerator.name();
  const validHref = "https://example.com/register";
  const validReferrer = "https://example.com/login";

  // Test 1: Attempt registration with a weak password (too short)
  const weakPasswordBody = {
    email: validEmail,
    password: "123", // Too short password (likely below minimum requirements)
    name: validName,
    href: validHref,
    referrer: validReferrer,
  } satisfies ITodoAppUser.ICreate;

  // Expect the API to reject weak passwords
  await TestValidator.error("weak password should be rejected", async () => {
    await api.functional.auth.user.join(connection, {
      body: weakPasswordBody,
    });
  });

  // Test 2: Attempt registration with another weak password scenario
  const veryShortPasswordBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "a", // Single character password
    name: RandomGenerator.name(),
    href: validHref,
    referrer: validReferrer,
  } satisfies ITodoAppUser.ICreate;

  await TestValidator.error(
    "very short password should be rejected",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: veryShortPasswordBody,
      });
    },
  );

  // Test 3: Verify that a valid password is accepted
  const validPasswordBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongPassword123!", // Valid password meeting requirements
    name: RandomGenerator.name(),
    href: validHref,
    referrer: validReferrer,
  } satisfies ITodoAppUser.ICreate;

  const validUser = await api.functional.auth.user.join(connection, {
    body: validPasswordBody,
  });

  // Verify the valid registration succeeded
  typia.assert(validUser);
  TestValidator.equals(
    "user email matches",
    validUser.email,
    validPasswordBody.email,
  );
  TestValidator.equals(
    "user name matches",
    validUser.name,
    validPasswordBody.name,
  );
  TestValidator.predicate(
    "user has valid ID",
    typia.is<string & tags.Format<"uuid">>(validUser.id),
  );
  TestValidator.predicate("user is active", validUser.status === "active");

  // Test 4: Test password length boundary (empty password)
  const emptyPasswordBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "", // Empty password
    name: RandomGenerator.name(),
    href: validHref,
    referrer: validReferrer,
  } satisfies ITodoAppUser.ICreate;

  await TestValidator.error("empty password should be rejected", async () => {
    await api.functional.auth.user.join(connection, {
      body: emptyPasswordBody,
    });
  });
}

