  });
  typia.assert(userWithName);

  TestValidator.equals(
    "user with name has correct email",
    userWithName.email,
    emailWithName,
  );
  TestValidator.equals(
    "user with name has provided name",
    userWithName.name,
    fullName,
  );
  TestValidator.predicate(
    "user with name has token",
    userWithName.token !== null,
  );
