    Math.min(smallPageSearch.data.length, 2),
    2,
  );

  // Verify all returned users are active
  for (const user of smallPageSearch.data) {
    TestValidator.equals(
      "all users in small page search should be active",
      user.status,
      "active",
    );
  }
}

