import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test bulk archiving of completed tasks to move them out of active view.
 * Create multiple tasks in completed status, then use bulk patch to archive
 * them. Validate that tasks are properly archived and response indicates
 * success. This tests cleanup workflows where users organize completed work.
 */
export async function test_api_bulk_task_archive_by_user(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new user account for authentication context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "securePassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // 2. Create multiple completed tasks that need to be archived
  const task1 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.content({ paragraphs: 2 }),
      status: "completed",
      priority: "medium",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task1);

  const task2 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 2 }),
      description: RandomGenerator.content({ paragraphs: 1 }),
      status: "completed",
      priority: "high",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task2);

  const task3 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 4 }),
      description: RandomGenerator.content({ paragraphs: 3 }),
      status: "completed",
      priority: "low",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task3);

  // Also create a pending task to ensure it doesn't get archived
  const pendingTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "pending",
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask);

  // 3. Use bulk patch operation to archive the completed tasks
  const bulkResponse = await api.functional.todoApp.user.tasks.bulk.bulkUpdate(
    connection,
    {
      body: {
        task_ids: [task1.id, task2.id, task3.id],
        action: "archive",
      } satisfies ITodoAppTask.IBulkRequest,
    },
  );
  typia.assert(bulkResponse);

  // 4. Validate that the bulk operation succeeded
  TestValidator.equals(
    "bulk archive success count",
    bulkResponse.success_count,
    3,
  );
  TestValidator.equals(
    "bulk archive failure count",
    bulkResponse.failure_count,
    0,
  );
  TestValidator.equals("bulk archive total count", bulkResponse.total_count, 3);
  TestValidator.equals(
    "bulk archive has errors",
    bulkResponse.has_errors,
    false,
  );
  TestValidator.equals(
    "bulk archive results length",
    bulkResponse.results.length,
    3,
  );

  // Validate individual task results
  for (const result of bulkResponse.results) {
    TestValidator.equals("individual task status", result.status, "success");
    TestValidator.predicate(
      "task has no error message",
      result.error_message === null || result.error_message === undefined,
    );
    TestValidator.equals("operation type", result.operation_type, "archive");
  }

  // 5. Verify the response structure contains expected task data
  const archivedTaskIds = bulkResponse.results.map((result) => result.task_id);
  TestValidator.predicate(
    "all completed tasks archived",
    archivedTaskIds.includes(task1.id) &&
      archivedTaskIds.includes(task2.id) &&
      archivedTaskIds.includes(task3.id),
  );

  // Verify that the pending task was not affected
  TestValidator.predicate(
    "pending task not in archived results",
    !archivedTaskIds.includes(pendingTask.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test extending a task's due date to accommodate schedule changes.
 *
 * This test validates the complete workflow of extending a task's due date
 * through PUT /todoApp/user/tasks/{taskId}. The test follows these steps:
 *
 * 1. Create a new user account with email-based authentication
 * 2. Create a task with an initial due date set to 1 year in the future
 * 3. Extend the due date to 2 years in the future to simulate schedule changes
 * 4. Verify the due date update is successful and timestamp updated
 * 5. Validate that the new due date stays within business constraints (future
 *    date)
 *
 * The test ensures proper datetime handling and validates that due date updates
 * work correctly for time-sensitive task organization in the Todo application.
 */
export async function test_api_task_update_due_date_extension(
  connection: api.IConnection,
) {
  // Step 1: Create user account for due date testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "TestPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/join",
      referrer: "https://example.com/login",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create task with due date to be extended
  const initialDueDate = new Date(
    Date.now() + 365 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 1 year from now
  const task = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 5 }),
      description: RandomGenerator.content({ paragraphs: 2 }),
      status: "pending",
      priority: RandomGenerator.pick([
        "none",
        "low",
        "medium",
        "high",
      ] as const),
      due_date: initialDueDate,
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task);

  // Verify initial task creation with proper due date
  TestValidator.equals(
    "task created with due date",
    task.due_date,
    initialDueDate,
  );
  TestValidator.equals("task status is pending", task.status, "pending");

  // Step 3: Extend due date to accommodate schedule changes
  const extendedDueDate = new Date(
    Date.now() + 730 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 2 years from now
  const updatedTask = await api.functional.todoApp.user.tasks.update(
    connection,
    {
      taskId: task.id,
      body: {
        due_date: extendedDueDate,
        status: "pending", // Keep status same
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(updatedTask);

  // Step 4: Verify due date update is successful
  TestValidator.equals(
    "task updated with extended due date",
    updatedTask.due_date,
    extendedDueDate,
  );
  TestValidator.equals("task id remains same", updatedTask.id, task.id);
  TestValidator.notEquals(
    "updated_at timestamp changed",
    updatedTask.updated_at,
    task.updated_at,
  );

  // Step 5: Validate business constraints
  TestValidator.predicate(
    "extended due date is in the future",
    new Date(updatedTask.due_date!).getTime() > Date.now(),
  );

  // Verify some task properties remain unchanged after update
  TestValidator.equals("task title unchanged", updatedTask.title, task.title);
  TestValidator.equals(
    "task description unchanged",
    updatedTask.description,
    task.description,
  );
  TestValidator.equals(
    "task priority unchanged",
    updatedTask.priority,
    task.priority,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_task_update_title_correction(
  connection: api.IConnection,
) {
  // 1. Authenticate a user for title correction testing
  const userEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userEmail,
        password: "1234",
        href: "https://example.com/register",
        referrer: "https://example.com/",
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(user);

  // 2. Create a task with an initial title that needs correction
  const originalTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "Complt proj#2 by Wenday", // Intentionally flawed title
        status: "pending",
        description: "Need to review and fix the presentation slides",
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(originalTask);

  // 3. Correct the task title to improve accuracy and clarity
  const correctedTitle = "Complete project #2 by Wednesday";
  const updatedTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: originalTask.id,
      body: {
        title: correctedTitle,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(updatedTask);

  // 4. Validate the title correction was successful
  TestValidator.equals(
    "Task ID remains unchanged",
    updatedTask.id,
    originalTask.id,
  );
  TestValidator.equals(
    "Title corrected successfully",
    updatedTask.title,
    correctedTitle,
  );
  TestValidator.equals(
    "Status unchanged",
    updatedTask.status,
    originalTask.status,
  );

  // 5. Test edge case: title at maximum length (200 characters)
  const maxLengthTitle = RandomGenerator.paragraph({
    sentences: 8,
    wordMin: 3,
    wordMax: 5,
  }); // Generate long title
  const truncatedTitle = maxLengthTitle.substring(0, 200); // Ensure exactly 200 characters
  const maxLengthTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: originalTask.id,
      body: {
        title: truncatedTitle,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(maxLengthTask);

  TestValidator.equals(
    "Maximum length title accepted",
    maxLengthTask.title,
    truncatedTitle,
  );
  TestValidator.predicate(
    "Title length within limit",
    maxLengthTask.title.length <= 200,
  );

  // 6. Test realistic title correction scenarios
  const improvementTests = [
    {
      from: "Call client tomorrw",
      to: "Call client tomorrow at 2 PM",
    },
    {
      from: "Fix db issue",
      to: "Fix database connection timeout issue in production",
    },
    {
      from: "Team mtg",
      to: "Weekly team status meeting - discuss Q4 goals",
    },
    {
      from: "Update docs",
      to: "Update API documentation with new authentication endpoints",
    },
  ];

  for (const test of improvementTests) {
    // Update to the test title
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: originalTask.id,
      body: {
        title: test.from,
      } satisfies ITodoAppTask.IUpdate,
    });

    // Now correct to the improved title
    const improvedTask: ITodoAppTask =
      await api.functional.todoApp.user.tasks.update(connection, {
        taskId: originalTask.id,
        body: {
          title: test.to,
        } satisfies ITodoAppTask.IUpdate,
      });
    typia.assert(improvedTask);

    TestValidator.equals(
      `Title improved from '${test.from}' to '${test.to}'`,
      improvedTask.title,
      test.to,
    );
    TestValidator.predicate(
      "Improved title provides more clarity",
      improvedTask.title.length > test.from.length,
    );
  }

  // 7. Test title correction with special characters and formatting
  const specialCharTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.update(connection, {
      taskId: originalTask.id,
      body: {
        title: "Review [PR#42] & check error handling (URGENT!)",
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(specialCharTask);

  TestValidator.predicate(
    "Special characters handled correctly",
    specialCharTask.title.includes("[") &&
      specialCharTask.title.includes("]") &&
      specialCharTask.title.includes("&") &&
      specialCharTask.title.includes("(") &&
      specialCharTask.title.includes(")"),
  );

  // 8. Verify task identification remains intact throughout updates
  TestValidator.equals(
    "Task ID consistent through updates",
    updatedTask.id,
    originalTask.id,
  );
  TestValidator.equals(
    "User ownership unchanged",
    updatedTask.user.id,
    user.id,
  );

  // Ensure updated_at timestamp is properly handled
  const updatedAtOriginal = new Date(originalTask.updated_at);
  const updatedAtLatest = new Date(updatedTask.updated_at);
  TestValidator.predicate(
    "Timestamps are valid dates",
    !isNaN(updatedAtOriginal.getTime()) && !isNaN(updatedAtLatest.getTime()),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
