import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation with all available fields. User creates fully-featured
 * tasks including title, description, priority, due date, and status. Validates
 * comprehensive task creation workflow, field validation, and complete task
 * data persistence including optional metadata handling.
 */
export async function test_api_task_creation_complete(
  connection: api.IConnection,
) {
  // Step 1: Create user account for task ownership
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePassword123!",
      name: RandomGenerator.name(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
      href: "https://example.com/register",
      referrer: "https://example.com/home",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create task 1 - Complete task with all fields
  const task1Data = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    status: "pending",
    priority: "high",
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
  } satisfies ITodoAppTask.ICreate;

  const task1 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: task1Data,
    },
  );
  typia.assert(task1);

  // Validate task 1 creation
  TestValidator.equals("task 1 title matches", task1.title, task1Data.title);
  TestValidator.equals(
    "task 1 description matches",
    task1.description,
    task1Data.description,
  );
  TestValidator.equals("task 1 status matches", task1.status, task1Data.status);
  TestValidator.equals(
    "task 1 priority matches",
    task1.priority,
    task1Data.priority,
  );
  TestValidator.equals(
    "task 1 due date matches",
    task1.due_date,
    task1Data.due_date,
  );
  TestValidator.equals("task 1 user ID matches", task1.user.id, user.id);
  TestValidator.predicate(
    "task 1 has created_at timestamp",
    task1.created_at !== null,
  );
  TestValidator.predicate(
    "task 1 has updated_at timestamp",
    task1.updated_at !== null,
  );
  TestValidator.predicate(
    "task 1 is not completed",
    task1.completed_at === null,
  );

  // Step 3: Create task 2 - Minimal task with required fields only
  const task2Data = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 6 }),
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const task2 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: task2Data,
    },
  );
  typia.assert(task2);

  // Validate task 2 creation (minimal fields)
  TestValidator.equals("task 2 title matches", task2.title, task2Data.title);
  TestValidator.equals("task 2 status matches", task2.status, task2Data.status);
  TestValidator.predicate(
    "task 2 description is null",
    task2.description === null,
  );
  TestValidator.predicate("task 2 priority is null", task2.priority === null);
  TestValidator.predicate("task 2 due_date is null", task2.due_date === null);
  TestValidator.equals("task 2 user ID matches", task2.user.id, user.id);

  // Step 4: Create task 3 - Task with completed status
  const task3Data = {
    title: RandomGenerator.paragraph({ sentences: 1, wordMin: 5, wordMax: 10 }),
    description: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 3,
      wordMax: 7,
    }),
    status: "completed",
    priority: "medium",
  } satisfies ITodoAppTask.ICreate;

  const task3 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: task3Data,
    },
  );
  typia.assert(task3);

  // Validate task 3 creation (completed status)
  TestValidator.equals("task 3 title matches", task3.title, task3Data.title);
  TestValidator.equals(
    "task 3 description matches",
    task3.description,
    task3Data.description,
  );
  TestValidator.equals("task 3 status matches", task3.status, task3Data.status);
  TestValidator.equals(
    "task 3 priority matches",
    task3.priority,
    task3Data.priority,
  );
  TestValidator.predicate(
    "task 3 has completed_at timestamp",
    task3.completed_at !== null,
  );
  TestValidator.equals("task 3 user ID matches", task3.user.id, user.id);

  // Step 5: Create task 4 - Task with different priority levels
  const priorities = ["none", "low", "medium", "high"] as const;
  const task4Data = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 9 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 7,
    }),
    status: "pending",
    priority: RandomGenerator.pick(priorities),
  } satisfies ITodoAppTask.ICreate;

  const task4 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: task4Data,
    },
  );
  typia.assert(task4);

  // Validate task 4 creation (random priority)
  TestValidator.equals("task 4 title matches", task4.title, task4Data.title);
  TestValidator.equals(
    "task 4 description matches",
    task4.description,
    task4Data.description,
  );
  TestValidator.equals("task 4 status matches", task4.status, task4Data.status);
  TestValidator.equals(
    "task 4 priority matches",
    task4.priority,
    task4Data.priority,
  );
  TestValidator.equals("task 4 user ID matches", task4.user.id, user.id);

  // Step 6: Validate all tasks share the same user ownership
  TestValidator.equals(
    "task 1 user matches created user",
    task1.user.id,
    user.id,
  );
  TestValidator.equals(
    "task 2 user matches created user",
    task2.user.id,
    user.id,
  );
  TestValidator.equals(
    "task 3 user matches created user",
    task3.user.id,
    user.id,
  );
  TestValidator.equals(
    "task 4 user matches created user",
    task4.user.id,
    user.id,
  );

  // Step 7: Validate task creation timestamps are consistent
  TestValidator.predicate(
    "task 1 created before updated",
    task1.created_at <= task1.updated_at,
  );
  TestValidator.predicate(
    "task 2 created before updated",
    task2.created_at <= task2.updated_at,
  );
  TestValidator.predicate(
    "task 3 created before updated",
    task3.created_at <= task3.updated_at,
  );
  TestValidator.predicate(
    "task 4 created before updated",
    task4.created_at <= task4.updated_at,
  );

  // Step 8: Validate completed tasks have completion timestamp
  TestValidator.predicate(
    "task 3 has completion timestamp",
    task3.completed_at !== null,
  );
  TestValidator.predicate(
    "pending tasks have no completion timestamp",
    task1.completed_at === null &&
      task2.completed_at === null &&
      task4.completed_at === null,
  );

  // Step 9: Validate user summary data consistency across all tasks
  TestValidator.equals(
    "all tasks have same user email",
    task1.user.email === task2.user.email &&
      task2.user.email === task3.user.email &&
      task3.user.email === task4.user.email &&
      task4.user.email === user.email,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test basic task search and filtering functionality in the Todo application.
 *
 * This test validates the task search and filtering capabilities by:
 *
 * 1. Creating a user account with proper authentication
 * 2. Creating multiple tasks with varied statuses (pending/completed) and
 *    priorities (none/low/medium/high)
 * 3. Testing basic filters - status filtering (pending tasks only)
 * 4. Testing priority filtering (high priority tasks only)
 * 5. Testing combined filtering (pending AND high priority)
 * 6. Verifying pagination functionality with different page sizes
 * 7. Validating text search across task titles
 * 8. Ensuring filters correctly narrow results and maintain data integrity
 *
 * The test ensures users can effectively organize and locate their tasks using
 * the filtering system.
 */
export async function test_api_task_search_basic_filtering(
  connection: api.IConnection,
) {
  // Create user account with email/password authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Define priority and status options for systematic task creation
  const priorities = ["none", "low", "medium", "high"] as const;
  const statuses = ["pending", "completed"] as const;

  // Create systematic test tasks - 2 of each priority/status combination
  const tasks: ITodoAppTask[] = [];

  // Create 16 tasks (4 priorities × 2 statuses × 2 tasks each)
  for (let i = 0; i < 16; i++) {
    const priority = priorities[i % 4];
    const status = statuses[Math.floor(i / 8)];

    const task = await api.functional.todoApp.user.users.tasks.create(
      connection,
      {
        userId: user.id,
        body: {
          title: `Task ${i + 1} - ${priority} priority ${status}`,
          description: RandomGenerator.paragraph({ sentences: 2 }),
          priority: priority,
          status: status,
          due_date:
            status === "pending" && Math.random() > 0.3
              ? new Date(
                  Date.now() + (i + 1) * 24 * 60 * 60 * 1000,
                ).toISOString()
              : null,
        } satisfies ITodoAppTask.ICreate,
      },
    );
    typia.assert(task);
    tasks.push(task);
  }

  // Test basic filtering - status=pending only
  TestValidator.predicate("total tasks created", tasks.length === 16);

  const pendingTasksResult =
    await api.functional.todoApp.user.users.tasks.index(connection, {
      userId: user.id,
      body: {
        status: "pending",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(pendingTasksResult);

  // Validate pending tasks filtering works correctly
  TestValidator.predicate(
    'all pending tasks have status="pending"',
    pendingTasksResult.data.every((task) => task.status === "pending"),
  );
  TestValidator.equals(
    "pending tasks page number correct",
    pendingTasksResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "pending tasks limit correct",
    pendingTasksResult.pagination.limit,
    10,
  );
  TestValidator.equals(
    "correct total pending tasks count",
    pendingTasksResult.pagination.records,
    8,
  ); // 8 pending tasks out of 16 total

  // Test priority filtering - priority=high only
  const highPriorityTasksResult =
    await api.functional.todoApp.user.users.tasks.index(connection, {
      userId: user.id,
      body: {
        priority: "high",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(highPriorityTasksResult);

  // Validate high priority tasks filtering
  TestValidator.predicate(
    'all high priority tasks have priority="high"',
    highPriorityTasksResult.data.every((task) => task.priority === "high"),
  );
  TestValidator.equals(
    "high priority tasks page number correct",
    highPriorityTasksResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "high priority tasks limit correct",
    highPriorityTasksResult.pagination.limit,
    10,
  );
  TestValidator.equals(
    "correct total high priority tasks count",
    highPriorityTasksResult.pagination.records,
    4,
  ); // 4 high priority tasks (2 pending + 2 completed)

  // Test combined filtering - status=pending AND priority=high
  const pendingHighPriorityResult =
    await api.functional.todoApp.user.users.tasks.index(connection, {
      userId: user.id,
      body: {
        status: "pending",
        priority: "high",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(pendingHighPriorityResult);

  // Validate combined filtering
  TestValidator.predicate(
    "combined filter tasks are all pending AND high priority",
    pendingHighPriorityResult.data.every(
      (task) => task.status === "pending" && task.priority === "high",
    ),
  );
  TestValidator.equals(
    "combined filter page number correct",
    pendingHighPriorityResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "combined filter limit correct",
    pendingHighPriorityResult.pagination.limit,
    10,
  );
  TestValidator.equals(
    "correct combined filtered task count",
    pendingHighPriorityResult.pagination.records,
    2,
  ); // 2 tasks with both pending + high priority

  // Test pagination - page 1 with 5 items per page
  const page1Size5Result = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page1Size5Result);

  TestValidator.equals(
    "page 1 returns exactly 5 tasks",
    page1Size5Result.data.length,
    5,
  );
  TestValidator.equals(
    "page 1 pagination metadata correct",
    page1Size5Result.pagination.limit,
    5,
  );
  TestValidator.equals(
    "page 1 total records correct",
    page1Size5Result.pagination.records,
    16,
  );
  TestValidator.predicate(
    "page 1 current page is 1",
    page1Size5Result.pagination.current === 1,
  );

  // Test pagination - page 2 with 5 items per page
  const page2Size5Result = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 2,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page2Size5Result);

  TestValidator.equals(
    "page 2 returns exactly 5 tasks",
    page2Size5Result.data.length,
    5,
  );
  TestValidator.equals(
    "page 2 pagination metadata correct",
    page2Size5Result.pagination.limit,
    5,
  );
  TestValidator.equals(
    "page 2 total records correct",
    page2Size5Result.pagination.records,
    16,
  );
  TestValidator.equals(
    "page 2 current page is 2",
    page2Size5Result.pagination.current,
    2,
  );

  // Test pagination handles remaining tasks correctly
  const page4Size5Result = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 4,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page4Size5Result);

  TestValidator.equals(
    "page 4 returns remaining 1 task",
    page4Size5Result.data.length,
    1,
  ); // 16 total - 5×3 = 1 remaining

  // Test text search functionality
  const searchResult = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        search: "Task 1",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResult);

  TestValidator.predicate(
    "search results contain search term",
    searchResult.data.every((task) => task.title.includes("Task 1")),
  );
  TestValidator.predicate(
    "search respects pagination settings",
    searchResult.pagination.current === 1 &&
      searchResult.pagination.limit === 10,
  );
  TestValidator.predicate(
    "search results are reasonable count",
    searchResult.pagination.records > 0 &&
      searchResult.pagination.records <= 16,
  );

  // Test filtering by low priority tasks with due dates
  const lowPriorityWithDue =
    await api.functional.todoApp.user.users.tasks.index(connection, {
      userId: user.id,
      body: {
        priority: "low",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    });
  typia.assert(lowPriorityWithDue);

  TestValidator.predicate(
    "low priority filter works correctly",
    lowPriorityWithDue.data.every((task) => task.priority === "low"),
  );
  TestValidator.equals(
    "low priority tasks count correct",
    lowPriorityWithDue.pagination.records,
    4,
  ); // 4 low priority tasks
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test search pagination functionality for todo tasks.
 *
 * This test validates the complete pagination workflow including:
 *
 * 1. User registration and authentication
 * 2. Creation of multiple tasks to test pagination (across multiple pages)
 * 3. Testing various pagination scenarios:
 *
 *    - Different page sizes (1, 5, 10, 50 items per page)
 *    - Different page numbers (first, middle, last, non-existent)
 *    - Edge cases (page 0, negative pages, page beyond total pages)
 * 4. Validation of pagination metadata accuracy
 * 5. Testing empty result scenarios
 * 6. Verifying consistent task ordering and data integrity
 *
 * The test ensures that pagination works correctly for task search operations
 * and handles all edge cases appropriately while maintaining data consistency.
 */
export async function test_api_task_search_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create a new user for testing
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "testPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create multiple tasks for pagination testing
  const taskCount = 15; // Create 15 tasks to test multiple pages
  const tasks = await ArrayUtil.asyncRepeat(taskCount, async () => {
    const title = `Task ${RandomGenerator.paragraph({ sentences: 3 })}`;
    const description = RandomGenerator.paragraph({ sentences: 5 });
    const priority = RandomGenerator.pick([
      "none",
      "low",
      "medium",
      "high",
    ] as const);
    const status = RandomGenerator.pick(["pending", "completed"] as const);

    return await api.functional.todoApp.user.users.tasks.create(connection, {
      userId: user.id,
      body: {
        title,
        description,
        priority,
        status,
      } satisfies ITodoAppTask.ICreate,
    });
  });

  // Validate all tasks were created successfully
  typia.assert(tasks);
  TestValidator.equals(
    "all tasks created successfully",
    tasks.length,
    taskCount,
  );

  // Step 3: Test pagination with different page sizes
  console.log("Testing pagination with different page sizes...");

  // Test with page size 1 (first page)
  const page1Size1 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 1,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page1Size1);
  TestValidator.equals(
    "page 1, size 1 has correct data count",
    page1Size1.data.length,
    1,
  );
  TestValidator.equals(
    "page 1, size 1 has correct current page",
    page1Size1.pagination.current,
    1,
  );
  TestValidator.equals(
    "page 1, size 1 has correct limit",
    page1Size1.pagination.limit,
    1,
  );
  TestValidator.equals(
    "page 1, size 1 has correct total records",
    page1Size1.pagination.records,
    taskCount,
  );
  TestValidator.equals(
    "page 1, size 1 has correct total pages",
    page1Size1.pagination.pages,
    taskCount,
  ); // 15 tasks, 1 per page = 15 pages

  // Test with page size 5 (first page)
  const page1Size5 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page1Size5);
  TestValidator.equals(
    "page 1, size 5 has correct data count",
    page1Size5.data.length,
    5,
  );
  TestValidator.equals(
    "page 1, size 5 has correct current page",
    page1Size5.pagination.current,
    1,
  );
  TestValidator.equals(
    "page 1, size 5 has correct limit",
    page1Size5.pagination.limit,
    5,
  );
  TestValidator.equals(
    "page 1, size 5 has correct total records",
    page1Size5.pagination.records,
    taskCount,
  );
  TestValidator.equals(
    "page 1, size 5 has correct total pages",
    page1Size5.pagination.pages,
    Math.ceil(taskCount / 5),
  ); // 3 pages

  // Test with page size 5 (last page)
  const page3Size5 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 3,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page3Size5);
  TestValidator.equals(
    "page 3, size 5 has correct data count",
    page3Size5.data.length,
    5,
  ); // Should have 5 tasks (tasks 11-15)
  TestValidator.equals(
    "page 3, size 5 has correct current page",
    page3Size5.pagination.current,
    3,
  );
  TestValidator.equals(
    "page 3, size 5 has correct limit",
    page3Size5.pagination.limit,
    5,
  );
  TestValidator.equals(
    "page 3, size 5 has correct total records",
    page3Size5.pagination.records,
    taskCount,
  );
  TestValidator.equals(
    "page 3, size 5 has correct total pages",
    page3Size5.pagination.pages,
    3,
  ); // 3 pages total

  // Test with page size 10 (middle page)
  const page2Size10 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 2,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page2Size10);
  TestValidator.equals(
    "page 2, size 10 has correct data count",
    page2Size10.data.length,
    5,
  ); // Should have 5 remaining tasks (11-15)
  TestValidator.equals(
    "page 2, size 10 has correct current page",
    page2Size10.pagination.current,
    2,
  );
  TestValidator.equals(
    "page 2, size 10 has correct limit",
    page2Size10.pagination.limit,
    10,
  );
  TestValidator.equals(
    "page 2, size 10 has correct total records",
    page2Size10.pagination.records,
    taskCount,
  );
  TestValidator.equals(
    "page 2, size 10 has correct total pages",
    page2Size10.pagination.pages,
    2,
  ); // 2 pages total

  // Step 4: Test edge cases
  console.log("Testing pagination edge cases...");

  // Test requesting page 0 (should start from page 1)
  const page0 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 0,
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(page0);
  TestValidator.equals(
    "page 0 should behave like page 1",
    page0.pagination.current,
    1,
  ); // Should normalize to page 1

  // Test requesting page beyond total pages
  const pageBeyond = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 100, // Way beyond total pages
        limit: 5,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pageBeyond);
  TestValidator.equals(
    "page beyond total pages should return empty",
    pageBeyond.data.length,
    0,
  );
  TestValidator.equals(
    "page beyond total pages should have current page as requested",
    pageBeyond.pagination.current,
    100,
  );
  TestValidator.equals(
    "page beyond total pages should have no records",
    pageBeyond.pagination.records,
    taskCount,
  );

  // Test with maximum limit (100)
  const maxLimit = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 100,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(maxLimit);
  TestValidator.equals(
    "max limit should return all tasks",
    maxLimit.data.length,
    taskCount,
  );
  TestValidator.equals(
    "max limit should have 1 page",
    maxLimit.pagination.pages,
    1,
  );

  // Step 5: Test with filters and pagination
  console.log("Testing pagination with filters...");

  // Filter by status = "pending" with pagination
  const pendingTasks = tasks.filter((task) => task.status === "pending");
  const pendingPage1 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 5,
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pendingPage1);
  TestValidator.predicate(
    "filtered pagination respects status filter",
    pendingPage1.data.every((task) => task.status === "pending"),
  );
  TestValidator.equals(
    "filtered pagination has correct total records",
    pendingPage1.pagination.records,
    pendingTasks.length,
  );

  // Filter by priority = "high" with pagination
  const highPriorityTasks = tasks.filter((task) => task.priority === "high");
  const highPage1 = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 5,
        priority: "high",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(highPage1);
  TestValidator.predicate(
    "filtered pagination respects priority filter",
    highPage1.data.every((task) => task.priority === "high"),
  );
  TestValidator.equals(
    "filtered pagination has correct total records",
    highPage1.pagination.records,
    highPriorityTasks.length,
  );

  // Test search with pagination
  const firstTaskTitle = tasks[0].title.substring(0, 10); // First 10 chars of first task title
  const searchPage = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 10,
        search: firstTaskTitle,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchPage);
  TestValidator.predicate(
    "search pagination finds matching tasks",
    searchPage.data.length >= 1,
  );
  TestValidator.predicate(
    "search pagination returns tasks containing search term",
    searchPage.data.every((task) => task.title.includes(firstTaskTitle)),
  );

  // Step 6: Test ordering with pagination
  console.log("Testing pagination with ordering...");

  // Test order by created_at DESC (should be default)
  const orderedDefault = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 15,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(orderedDefault);
  // Validate creation timestamps are in descending order (newest first)
  let isDescendingOrder = true;
  for (let i = 0; i < orderedDefault.data.length - 1; i++) {
    const current = new Date(orderedDefault.data[i].created_at).getTime();
    const next = new Date(orderedDefault.data[i + 1].created_at).getTime();
    if (current < next) {
      isDescendingOrder = false;
      break;
    }
  }
  TestValidator.predicate(
    "default ordering by created_at DESC",
    isDescendingOrder,
  );

  // Test order by title ASC
  const orderedByTitle = await api.functional.todoApp.user.users.tasks.index(
    connection,
    {
      userId: user.id,
      body: {
        page: 1,
        limit: 15,
        order_by: "title",
        order_direction: "asc",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(orderedByTitle);
  // Validate titles are in ascending order
  let isAscendingOrder = true;
  for (let i = 0; i < orderedByTitle.data.length - 1; i++) {
    if (orderedByTitle.data[i].title > orderedByTitle.data[i + 1].title) {
      isAscendingOrder = false;
      break;
    }
  }
  TestValidator.predicate("ordering by title ASC", isAscendingOrder);

  console.log("Pagination testing completed successfully!");
}

