import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_task_creation_completed_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create a new user for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "testPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/register",
      referrer: "https://example.com/home",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // 2. Create task with completed status
  const taskTitle = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 3,
    wordMax: 8,
  });
  const taskDescription = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 5,
    wordMax: 10,
  });

  const completedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: taskTitle,
        description: taskDescription,
        status: "completed",
        priority: "high",
        due_date: typia.random<string & tags.Format<"date-time">>(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask);

  // 3. Validate task creation with completed status
  TestValidator.equals(
    "task has completed status",
    completedTask.status,
    "completed",
  );

  // 4. Verify completed_at timestamp is set immediately
  TestValidator.predicate(
    "completed_at timestamp exists",
    completedTask.completed_at !== null &&
      completedTask.completed_at !== undefined,
  );
  TestValidator.predicate(
    "completed_at is valid date",
    new Date(completedTask.completed_at!).toString() !== "Invalid Date",
  );

  // 5. Verify all task fields are properly set
  TestValidator.equals("task title matches", completedTask.title, taskTitle);
  TestValidator.equals(
    "task description matches",
    completedTask.description,
    taskDescription,
  );
  TestValidator.equals("task priority matches", completedTask.priority, "high");
  TestValidator.predicate(
    "task has user information",
    completedTask.user !== null && completedTask.user !== undefined,
  );
  TestValidator.equals("task user ID matches", completedTask.user.id, user.id);
  TestValidator.equals(
    "task user email matches",
    completedTask.user.email,
    user.email,
  );
  TestValidator.predicate(
    "task created_at exists",
    completedTask.created_at !== null && completedTask.created_at !== undefined,
  );
  TestValidator.predicate(
    "task updated_at exists",
    completedTask.updated_at !== null && completedTask.updated_at !== undefined,
  );

  // 6. Verify timestamps are reasonable (completed_at should be after created_at or equal)
  const createdAt = new Date(completedTask.created_at);
  const completedAt = new Date(completedTask.completed_at!);
  TestValidator.predicate(
    "completed_at is after or equal to created_at",
    completedAt.getTime() >= createdAt.getTime(),
  );

  // 7. Validate due_date is preserved
  TestValidator.predicate(
    "due_date is preserved",
    completedTask.due_date !== null && completedTask.due_date !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_task_creation_max_title_length(
  connection: api.IConnection,
) {
  // Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      name: RandomGenerator.name(),
      href: "https://example.com/registration",
      referrer: "https://example.com/referral",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Generate a title with exactly 200 characters (maximum allowed)
  const maxTitle = ArrayUtil.repeat(200, (i) => "A").join("");

  // Test task creation with exactly 200 character title (should succeed)
  const taskWithMaxTitle = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: maxTitle,
        status: "pending",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskWithMaxTitle);
  TestValidator.equals("max title length accepted", maxTitle.length, 200);
  TestValidator.equals(
    "task created with max title",
    taskWithMaxTitle.title,
    maxTitle,
  );
  TestValidator.equals(
    "task status correct",
    taskWithMaxTitle.status,
    "pending",
  );

  // Test task creation with 201 character title (should fail)
  const overLimitTitle = maxTitle + "X";
  TestValidator.equals("over limit title length", overLimitTitle.length, 201);

  await TestValidator.error(
    "title exceeding 200 characters should fail",
    async () => {
      await api.functional.todoApp.user.tasks.create(connection, {
        body: {
          title: overLimitTitle,
          status: "pending",
        } satisfies ITodoAppTask.ICreate,
      });
    },
  );

  // Validate the actual title lengths and boundary conditions
  TestValidator.predicate(
    "max title has exactly 200 characters",
    maxTitle.length === 200,
  );
  TestValidator.predicate(
    "over limit title exceeds 200 characters",
    overLimitTitle.length === 201,
  );

  // Verify successful task has proper title length constraint
  TestValidator.predicate(
    "created task title matches constraint",
    taskWithMaxTitle.title.length === 200,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation with all available fields populated including title,
 * description, status, priority, and due date. Validates that comprehensive
 * task creation works correctly and that all fields are properly validated,
 * stored, and returned in the response.
 *
 * Test flow:
 *
 * 1. Create authenticated user through user registration
 * 2. Create task with all available fields populated
 * 3. Validate that all fields are correctly returned in the response
 * 4. Verify that the task belongs to the authenticated user
 * 5. Check that timestamps and metadata are properly set
 */
export async function test_api_task_creation_all_fields(
  connection: api.IConnection,
) {
  // Create authenticated user first (required dependency)
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userEmail,
        password: "SecurePassword123!",
        name: RandomGenerator.name(),
        href: "https://todoapp.com/register",
        referrer: "https://todoapp.com/login",
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(user);

  // Create task with all available fields populated
  const dueDate = new Date();
  dueDate.setDate(dueDate.getDate() + 30); // Due date 30 days from now (within 5 years limit)

  const taskData = {
    title: RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 6,
    }),
    status: "pending",
    priority: RandomGenerator.pick(["none", "low", "medium", "high"]),
    due_date: dueDate.toISOString(),
  } satisfies ITodoAppTask.ICreate;

  const task: ITodoAppTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: taskData,
    },
  );
  typia.assert(task);

  // Validate all fields are correctly returned
  TestValidator.equals("task title matches input", task.title, taskData.title);
  TestValidator.equals(
    "task description matches input",
    task.description,
    taskData.description,
  );
  TestValidator.equals(
    "task status matches input",
    task.status,
    taskData.status,
  );
  TestValidator.equals(
    "task priority matches input",
    task.priority,
    taskData.priority,
  );
  TestValidator.equals(
    "task due_date matches input",
    task.due_date,
    taskData.due_date,
  );

  // Verify task ownership
  TestValidator.equals(
    "task user ID matches authenticated user",
    task.user.id,
    user.id,
  );
  TestValidator.equals(
    "task user email matches authenticated user",
    task.user.email,
    user.email,
  );

  // Validate metadata fields
  TestValidator.predicate(
    "task has valid ID",
    typia.is<string & tags.Format<"uuid">>(task.id),
  );
  TestValidator.predicate(
    "task has creation timestamp",
    typia.is<string & tags.Format<"date-time">>(task.created_at),
  );
  TestValidator.predicate(
    "task has update timestamp",
    typia.is<string & tags.Format<"date-time">>(task.updated_at),
  );
  TestValidator.equals("task is not deleted", task.deleted_at, null);
  TestValidator.equals("task is not completed", task.completed_at, null);

  // Test creating a minimal task (testing optional field handling)
  const minimalTaskData = {
    title: RandomGenerator.paragraph({ sentences: 1, wordMin: 2, wordMax: 5 }),
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const minimalTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: minimalTaskData,
    });
  typia.assert(minimalTask);

  TestValidator.equals(
    "minimal task title matches",
    minimalTask.title,
    minimalTaskData.title,
  );
  TestValidator.equals(
    "minimal task status matches",
    minimalTask.status,
    minimalTaskData.status,
  );
  TestValidator.equals(
    "minimal task description is null",
    minimalTask.description,
    null,
  );
  TestValidator.equals(
    "minimal task priority is null",
    minimalTask.priority,
    null,
  );
  TestValidator.equals(
    "minimal task due_date is null",
    minimalTask.due_date,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation without proper authentication. Validates that the API
 * correctly rejects unauthenticated requests and returns appropriate error
 * responses. Ensures task creation is properly protected and requires valid
 * user authentication.
 */
export async function test_api_task_creation_unauthenticated(
  connection: api.IConnection,
) {
  // Step 1: Create an unauthenticated connection by clearing authentication headers
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // Step 2: Generate valid task creation data
  const taskData = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    status: "pending",
    priority: RandomGenerator.pick(["none", "low", "medium", "high"] as const),
  } satisfies ITodoAppTask.ICreate;

  // Step 3: Attempt to create task without authentication - should fail
  await TestValidator.error(
    "task creation without authentication should fail",
    async () => {
      await api.functional.todoApp.user.tasks.create(unauthConnection, {
        body: taskData,
      });
    },
  );

  // Step 4: Verify that the API properly rejects the request
  // Additional verification: Ensure the task data itself is valid for comparison
  const taskDataPreview = typia.random<ITodoAppTask.ICreate>();

  TestValidator.predicate(
    "generated task data is valid",
    typia.is<ITodoAppTask.ICreate>(taskData) && taskData.status === "pending",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation through the user-scoped POST
 * /todoApp/user/users/{userId}/tasks endpoint.
 *
 * Validates complete task creation workflow including title validation up to
 * 200 characters, optional description support up to 1000 characters, priority
 * level assignment (none, low, medium, high), status management
 * (pending/completed), and optional due date configuration. Ensures created
 * tasks are properly associated with the authenticated user and include
 * server-generated metadata like timestamps and unique identifiers.
 *
 * Test flow:
 *
 * 1. Create user account with email/password authentication
 * 2. Create multiple task configurations to test different scenarios
 * 3. Validate response structure, user association, and server-generated metadata
 */
export async function test_api_user_scoped_task_creation(
  connection: api.IConnection,
) {
  // Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const registeredUser = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(registeredUser);

  // Test 1: Create basic task with minimal required fields
  const basicTaskBody = {
    title: "Complete project documentation",
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const basicTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: basicTaskBody,
    },
  );
  typia.assert(basicTask);

  // Validate basic task creation
  TestValidator.equals(
    "basic task user ID matches",
    basicTask.user.id,
    registeredUser.id,
  );
  TestValidator.equals(
    "basic task title matches",
    basicTask.title,
    basicTaskBody.title,
  );
  TestValidator.equals(
    "basic task status matches",
    basicTask.status,
    basicTaskBody.status,
  );

  // Test 2: Create task with description
  const describedTaskBody = {
    title: "Review code changes in PR #123",
    description:
      "Focus on authentication logic and error handling. Ensure proper error propagation to the frontend.",
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const describedTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: describedTaskBody,
    },
  );
  typia.assert(describedTask);

  TestValidator.equals(
    "described task title matches",
    describedTask.title,
    describedTaskBody.title,
  );
  TestValidator.equals(
    "described task description matches",
    describedTask.description,
    describedTaskBody.description,
  );
  TestValidator.equals(
    "described task status matches",
    describedTask.status,
    describedTaskBody.status,
  );

  // Test 3: Create task with priority level
  const priorityTaskBody = {
    title: "Fix security vulnerability in API endpoint",
    priority: "high",
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const priorityTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: priorityTaskBody,
    },
  );
  typia.assert(priorityTask);

  TestValidator.equals(
    "priority task title matches",
    priorityTask.title,
    priorityTaskBody.title,
  );
  TestValidator.equals(
    "priority task priority matches",
    priorityTask.priority,
    priorityTaskBody.priority,
  );

  // Test 4: Create task with due date
  const dueDateTaskBody = {
    title: "Submit quarterly report",
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // One week from now
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const dueDateTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: dueDateTaskBody,
    },
  );
  typia.assert(dueDateTask);

  TestValidator.equals(
    "due date task title matches",
    dueDateTask.title,
    dueDateTaskBody.title,
  );
  TestValidator.equals(
    "due date task due_date matches",
    dueDateTask.due_date,
    dueDateTaskBody.due_date,
  );

  // Test 5: Create completed task
  const completedTaskBody = {
    title: "Finished database schema migration",
    description:
      "Successfully migrated production database to new schema version with zero downtime.",
    priority: "medium",
    status: "completed",
  } satisfies ITodoAppTask.ICreate;

  const completedTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: completedTaskBody,
    },
  );
  typia.assert(completedTask);

  TestValidator.equals(
    "completed task title matches",
    completedTask.title,
    completedTaskBody.title,
  );
  TestValidator.equals(
    "completed task description matches",
    completedTask.description,
    completedTaskBody.description,
  );
  TestValidator.equals(
    "completed task priority matches",
    completedTask.priority,
    completedTaskBody.priority,
  );
  TestValidator.equals(
    "completed task status matches",
    completedTask.status,
    completedTaskBody.status,
  );
  TestValidator.predicate(
    "completed task has completed_at timestamp",
    completedTask.completed_at !== null &&
      completedTask.completed_at !== undefined,
  );

  // Test 6: Create task with maximum title length
  const maxTitleTaskBody = {
    title: RandomGenerator.alphaNumeric(200), // Maximum 200 characters
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const maxTitleTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: maxTitleTaskBody,
    },
  );
  typia.assert(maxTitleTask);

  TestValidator.equals(
    "max title task title length equals 200",
    maxTitleTask.title.length,
    200,
  );
  TestValidator.equals(
    "max title task status matches",
    maxTitleTask.status,
    maxTitleTaskBody.status,
  );

  // Test 7: Create task with maximum description length
  const maxDescriptionTaskBody = {
    title: "Task with detailed description",
    description: RandomGenerator.content({
      paragraphs: 5,
      sentenceMin: 15,
      sentenceMax: 25,
      wordMin: 4,
      wordMax: 8,
    }),
    status: "pending",
  } satisfies ITodoAppTask.ICreate;

  const maxDescriptionTask =
    await api.functional.todoApp.user.users.tasks.create(connection, {
      userId: registeredUser.id,
      body: maxDescriptionTaskBody,
    });
  typia.assert(maxDescriptionTask);

  TestValidator.predicate(
    "max description task description length is at most 1000",
    maxDescriptionTask.description!.length <= 1000,
  );
  TestValidator.equals(
    "max description task status matches",
    maxDescriptionTask.status,
    maxDescriptionTaskBody.status,
  );

  // Test 8: Create task with all available fields
  const fullTaskBody = {
    title: "Comprehensive task with all fields populated",
    description:
      "This task demonstrates the use of all available task creation fields including priority levels and due dates.",
    status: "pending",
    priority: "low",
    due_date: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 days from now
  } satisfies ITodoAppTask.ICreate;

  const fullTask = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: registeredUser.id,
      body: fullTaskBody,
    },
  );
  typia.assert(fullTask);

  TestValidator.equals(
    "full task title matches",
    fullTask.title,
    fullTaskBody.title,
  );
  TestValidator.equals(
    "full task description matches",
    fullTask.description,
    fullTaskBody.description,
  );
  TestValidator.equals(
    "full task status matches",
    fullTask.status,
    fullTaskBody.status,
  );
  TestValidator.equals(
    "full task priority matches",
    fullTask.priority,
    fullTaskBody.priority,
  );
  TestValidator.equals(
    "full task due_date matches",
    fullTask.due_date,
    fullTaskBody.due_date,
  );

  // Validate that all tasks are properly associated with the authenticated user
  const allTasks = [
    basicTask,
    describedTask,
    priorityTask,
    dueDateTask,
    completedTask,
    maxTitleTask,
    maxDescriptionTask,
    fullTask,
  ];

  allTasks.forEach((task, index) => {
    TestValidator.predicate(
      `task ${index + 1} has user summary`,
      task.user !== null && task.user !== undefined,
    );
    TestValidator.equals(
      `task ${index + 1} user ID matches`,
      task.user.id,
      registeredUser.id,
    );
    TestValidator.equals(
      `task ${index + 1} user email matches`,
      task.user.email,
      registeredUser.email,
    );

    // Validate timestamps are generated by server
    TestValidator.predicate(
      `task ${index + 1} has valid created_at`,
      new Date(task.created_at).getTime() > 0,
    );
    TestValidator.predicate(
      `task ${index + 1} has valid updated_at`,
      new Date(task.updated_at).getTime() > 0,
    );
    TestValidator.predicate(
      `task ${index + 1} updated_at >= created_at`,
      new Date(task.updated_at).getTime() >=
        new Date(task.created_at).getTime(),
    );
  });

  // Test with different priority levels
  const priorityLevels = ["none", "low", "medium", "high"] as const;

  const priorityTasks = await ArrayUtil.asyncRepeat(
    priorityLevels.length,
    async (index) => {
      const priority = priorityLevels[index];
      const taskBody = {
        title: `Task with ${priority} priority`,
        priority: priority,
        status: "pending",
      } satisfies ITodoAppTask.ICreate;

      return await api.functional.todoApp.user.users.tasks.create(connection, {
        userId: registeredUser.id,
        body: taskBody,
      });
    },
  );

  priorityTasks.forEach((task, index) => {
    TestValidator.equals(
      `priority task ${index + 1} priority matches`,
      task.priority,
      priorityLevels[index],
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test comprehensive task creation using all available properties including
 * title with maximum length limits, detailed descriptions, priority levels,
 * status settings, and future due dates. Validates that the system accepts
 * high-priority tasks with extensive descriptions and due dates set up to 5
 * years in the future. Verifies that all user-provided data is preserved
 * exactly during the creation process with proper server-side validation and
 * metadata assignment.
 */
export async function test_api_task_creation_with_all_properties(
  connection: IConnection,
) {
  // Create user account for authentication
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      href: `https://example.com/register`,
      referrer: `https://example.com/referral`,
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Generate task with maximum title length (200 characters)
  const maxTitle = RandomGenerator.alphabets(200);

  // Create comprehensive description (up to 1000 characters)
  const detailedDescription = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 10,
    sentenceMax: 20,
    wordMin: 4,
    wordMax: 8,
  }).substring(0, 1000);

  // Set due date 5 years in the future
  const futureDueDate = new Date();
  futureDueDate.setFullYear(futureDueDate.getFullYear() + 5);

  // Create high-priority task with all properties
  const comprehensiveTask =
    await api.functional.todoApp.user.users.tasks.create(connection, {
      userId: user.id,
      body: {
        title: maxTitle,
        description: detailedDescription,
        status: "pending",
        priority: "high",
        due_date: futureDueDate.toISOString(),
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(comprehensiveTask);

  // Verify all properties are preserved exactly
  TestValidator.equals(
    "task title matches input exactly",
    comprehensiveTask.title,
    maxTitle,
  );
  TestValidator.equals(
