import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test complete task update workflow including modification of title and
 * description fields. Validates that users can successfully update existing
 * tasks created through POST /todoApp/user/tasks, modify title text within
 * 200-character limits, update descriptions up to 1000 characters, and verify
 * that changes are persisted with updated timestamps. Ensures the update
 * operation maintains task identity while allowing content modifications.
 *
 * 1. Create a new user account through user registration
 * 2. Create an original task with title and description
 * 3. Update the task title with new content within 200-character limit
 * 4. Update the task description with new content within 1000-character limit
 * 5. Update both title and description simultaneously
 * 6. Verify that updated timestamps are properly set
 * 7. Confirm task identity is maintained throughout updates
 */
export async function test_api_task_title_and_description_update(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account through user registration
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "securePassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create an original task with title and description
  const originalTitle = RandomGenerator.paragraph({ sentences: 3, wordMax: 5 });
  const originalDescription = RandomGenerator.content({
    paragraphs: 2,
    sentenceMin: 3,
    sentenceMax: 5,
  });

  const originalTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: originalTitle,
        description: originalDescription,
        status: "pending",
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(originalTask);

  // Step 3: Update only the task title with new content within 200-character limit
  const newTitle = RandomGenerator.paragraph({ sentences: 4, wordMax: 6 });
  const titleUpdateResult =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: originalTask.id,
      body: {
        title: newTitle,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(titleUpdateResult);

  // Verify title was updated while description remained unchanged
  TestValidator.equals("task title updated", titleUpdateResult.title, newTitle);
  TestValidator.equals(
    "task description unchanged",
    titleUpdateResult.description,
    originalDescription,
  );
  TestValidator.predicate(
    "updated timestamp changed",
    titleUpdateResult.updated_at !== originalTask.updated_at,
  );
  TestValidator.equals(
    "task id maintained",
    titleUpdateResult.id,
    originalTask.id,
  );

  // Step 4: Update only the task description with new content within 1000-character limit
  const newDescription = RandomGenerator.content({
    paragraphs: 3,
    sentenceMin: 4,
    sentenceMax: 6,
  });
  const descUpdateResult = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: originalTask.id,
      body: {
        description: newDescription,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(descUpdateResult);

  // Verify description was updated while title remained from previous update
  TestValidator.equals(
    "task title maintained",
    descUpdateResult.title,
    newTitle,
  );
  TestValidator.equals(
    "task description updated",
    descUpdateResult.description,
    newDescription,
  );
  TestValidator.predicate(
    "updated timestamp changed again",
    descUpdateResult.updated_at !== titleUpdateResult.updated_at,
  );
  TestValidator.equals(
    "task id maintained",
    descUpdateResult.id,
    originalTask.id,
  );

  // Step 5: Update both title and description simultaneously
  const finalTitle = RandomGenerator.paragraph({ sentences: 5, wordMax: 4 });
  const finalDescription = RandomGenerator.content({
    paragraphs: 4,
    sentenceMin: 2,
    sentenceMax: 4,
  });
  const finalUpdateResult =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: originalTask.id,
      body: {
        title: finalTitle,
        description: finalDescription,
        status: "completed",
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(finalUpdateResult);

  // Verify both fields were updated and status changed
  TestValidator.equals(
    "final title updated",
    finalUpdateResult.title,
    finalTitle,
  );
  TestValidator.equals(
    "final description updated",
    finalUpdateResult.description,
    finalDescription,
  );
  TestValidator.equals(
    "status updated to completed",
    finalUpdateResult.status,
    "completed",
  );
  TestValidator.predicate(
    "updated timestamp changed again",
    finalUpdateResult.updated_at !== descUpdateResult.updated_at,
  );
  TestValidator.equals(
    "task id maintained",
    finalUpdateResult.id,
    originalTask.id,
  );

  // Step 6: Verify that created_at timestamp remained unchanged while updated_at changed
  TestValidator.equals(
    "created_at timestamp unchanged",
    finalUpdateResult.created_at,
    originalTask.created_at,
  );
  TestValidator.predicate(
    "updated_at timestamp is more recent",
    finalUpdateResult.updated_at > originalTask.updated_at,
  );

  // Step 7: Verify task ownership is maintained
  TestValidator.equals(
    "task user id unchanged",
    finalUpdateResult.user.id,
    user.id,
  );
  TestValidator.equals(
    "task user email unchanged",
    finalUpdateResult.user.email,
    user.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task completion workflow that validates status transition from pending
 * to completed.
 *
 * This comprehensive test exercises the complete task lifecycle:
 *
 * 1. Creates a new user account with proper authentication
 * 2. Creates a fresh todo task with pending status
 * 3. Transitions the task from pending to completed status
 * 4. Validates automatic completion timestamp generation
 * 5. Verifies task metadata updates correctly
 *
 * The test ensures proper task ownership validation and status transition
 * handling while maintaining data integrity through the completion process.
 */
export async function test_api_task_status_completion_workflow(
  connection: api.IConnection,
) {
  // Create a new user account for authenticated operations
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "securePassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com/todo-app",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Create initial task with pending status
  const dueDate = new Date();
  dueDate.setDate(dueDate.getDate() + 1); // Tomorrow

  const pendingTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 8,
        }),
        description: RandomGenerator.paragraph({
          sentences: 5,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: RandomGenerator.pick([
          "none",
          "low",
          "medium",
          "high",
        ] as const),
        due_date: dueDate.toISOString(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask);

  // Verify task is initially created with pending status
  TestValidator.equals(
    "task status should be pending initially",
    pendingTask.status,
    "pending",
  );
  TestValidator.predicate(
    "completed_at should be null for pending tasks",
    pendingTask.completed_at === null && pendingTask.completed_at !== undefined,
  );

  // Update the task to completed status
  const completedTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: pendingTask.id,
      body: { status: "completed" } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(completedTask);

  // Validate status transition
  TestValidator.equals(
    "task status should be completed after update",
    completedTask.status,
    "completed",
  );

  // Validate auto-generation of completion timestamp
  TestValidator.predicate(
    "completed_at should not be null after completion",
    completedTask.completed_at !== null &&
      completedTask.completed_at !== undefined,
  );

  // Validate the completion timestamp format and recency
  const completionDate = new Date(
    typia.assert<string>(completedTask.completed_at),
  );
  const now = new Date();
  const oneMinuteAgo = new Date(now.getTime() - 60 * 1000);

  TestValidator.predicate(
    "completion timestamp should be valid ISO format",
    !isNaN(completionDate.getTime()),
  );
  TestValidator.predicate(
    "completion timestamp should be recent (within last minute)",
    completionDate >= oneMinuteAgo,
  );
  TestValidator.predicate(
    "completion timestamp should not be in the future",
    completionDate <= now,
  );

  // Validate task metadata is preserved
  TestValidator.equals(
    "task ID should remain the same",
    completedTask.id,
    pendingTask.id,
  );
  TestValidator.equals(
    "task title should remain unchanged",
    completedTask.title,
    pendingTask.title,
  );
  TestValidator.equals(
    "task description should remain unchanged",
    completedTask.description,
    pendingTask.description,
  );
  TestValidator.equals(
    "task priority should remain unchanged",
    completedTask.priority,
    pendingTask.priority,
  );
  TestValidator.equals(
    "task due_date should remain unchanged",
    completedTask.due_date,
    pendingTask.due_date,
  );
  TestValidator.equals(
    "user assignment should remain unchanged",
    completedTask.user.id,
    pendingTask.user.id,
  );

  // Validate timestamp progression
  TestValidator.predicate(
    "updated_at should be more recent than created_at after completion update",
    new Date(completedTask.updated_at).getTime() >=
      new Date(pendingTask.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task re-prioritization and due date management through partial updates.
 *
 * Validates that users can modify task priority levels (none, low, medium,
 * high), update due dates to reflect scheduling changes, and perform selective
 * field updates without affecting unchanged properties. Ensures partial updates
 * work correctly with timestamp tracking and that updated tasks maintain their
 * original required fields like title and mandatory properties.
 */
export async function test_api_task_priority_and_due_date_management(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "securePassword123",
      href: "https://example.com/register",
      referrer: "https://example.com/home",
      name: RandomGenerator.name(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create baseline task with specific priority and due date
  const originalDueDate = new Date(
    Date.now() + 7 * 24 * 60 * 60 * 1000,
  ).toISOString(); // One week from now
  const baselineTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 7,
        }),
        description: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 4,
          wordMax: 8,
        }),
        status: "pending",
        priority: "medium",
        due_date: originalDueDate,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(baselineTask);

  // Step 3: Test priority update from medium to high
  const highPriorityTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        priority: "high",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(highPriorityTask);
  TestValidator.equals(
    "priority updated to high",
    highPriorityTask.priority,
    "high",
  );
  TestValidator.equals(
    "title should remain unchanged",
    highPriorityTask.title,
    baselineTask.title,
  );
  TestValidator.equals(
    "description should remain unchanged",
    highPriorityTask.description,
    baselineTask.description,
  );

  // Step 4: Test priority update from high to low
  const lowPriorityTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        priority: "low",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(lowPriorityTask);
  TestValidator.equals(
    "priority updated to low",
    lowPriorityTask.priority,
    "low",
  );
  TestValidator.equals(
    "title should remain unchanged",
    lowPriorityTask.title,
    baselineTask.title,
  );

  // Step 5: Test priority update from low to none
  const noPriorityTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        priority: "none",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(noPriorityTask);
  TestValidator.equals(
    "priority updated to none",
    noPriorityTask.priority,
    "none",
  );

  // Step 6: Test due date update
  const newDueDate = new Date(
    Date.now() + 14 * 24 * 60 * 60 * 1000,
  ).toISOString(); // Two weeks from now
  const dueDateUpdatedTask =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        due_date: newDueDate,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(dueDateUpdatedTask);
  TestValidator.equals(
    "due date updated correctly",
    dueDateUpdatedTask.due_date,
    newDueDate,
  );
  TestValidator.equals(
    "priority should remain unchanged",
    dueDateUpdatedTask.priority,
    noPriorityTask.priority,
  );
  TestValidator.equals(
    "title should remain unchanged",
    dueDateUpdatedTask.title,
    baselineTask.title,
  );

  // Step 7: Test simultaneous priority and due date update
  const finalDueDate = new Date(
    Date.now() + 21 * 24 * 60 * 60 * 1000,
  ).toISOString(); // Three weeks from now
  const combinedUpdateTask =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        priority: "medium",
        due_date: finalDueDate,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(combinedUpdateTask);
  TestValidator.equals(
    "priority updated to medium",
    combinedUpdateTask.priority,
    "medium",
  );
  TestValidator.equals(
    "due date updated correctly",
    combinedUpdateTask.due_date,
    finalDueDate,
  );
  TestValidator.equals(
    "description should remain unchanged",
    combinedUpdateTask.description,
    baselineTask.description,
  );

  // Step 8: Verify updated_at timestamp tracking
  TestValidator.predicate(
    "updated_at timestamp should change",
    combinedUpdateTask.updated_at !== baselineTask.updated_at,
  );
  TestValidator.predicate(
    "updated_at should be after created_at",
    new Date(combinedUpdateTask.updated_at).getTime() >=
      new Date(baselineTask.created_at).getTime(),
  );

  // Step 9: Verify task maintains original required fields
  TestValidator.equals(
    "task ID unchanged",
    combinedUpdateTask.id,
    baselineTask.id,
  );
  TestValidator.equals(
    "task title unchanged",
    combinedUpdateTask.title,
    baselineTask.title,
  );
  TestValidator.equals(
    "task status unchanged when not specified",
    combinedUpdateTask.status,
    baselineTask.status,
  );
  TestValidator.equals(
    "user ownership unchanged",
    combinedUpdateTask.user.id,
    user.id,
  );

  // Step 10: Test removing due date (setting to null)
  const noDueDateTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: baselineTask.id,
      body: {
        due_date: null,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(noDueDateTask);
  TestValidator.equals(
    "due date should be null after removal",
    noDueDateTask.due_date,
    null,
  );
  TestValidator.equals(
    "priority should remain unchanged",
    noDueDateTask.priority,
    "medium",
  );
}

