import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test comprehensive task updates modifying multiple properties simultaneously
 * including title, description, status, priority, and due date. Validates that
 * complex partial updates preserve all user modifications while leaving
 * unspecified properties unchanged.
 *
 * This test implements a comprehensive workflow to validate multi-field task
 * updates:
 *
 * 1. User registration and authentication
 * 2. Task creation with specific initial properties
 * 3. Multiple partial updates testing different property combinations
 * 4. Validation of partial update behavior
 *
 * The test demonstrates that the update API properly handles:
 *
 * - Simultaneous updates to multiple fields (title, description, priority,
 *   status, due date)
 * - Partial updates that leave some fields unchanged
 * - Status transitions from pending to completed
 * - Due date validation within 5-year constraint
 * - Title length validation with 200-character maximum
 * - Property preservation when fields are not specified in update
 */
export async function test_api_task_multifield_update(
  connection: api.IConnection,
) {
  // Step 1: User registration and authentication
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "TestPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo/app",
      referrer: "https://example.com/auth/join",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create initial task with comprehensive properties
  const originalTitle = "Original Task Title for Multi-field Update Testing";
  const originalDescription =
    "This task was created specifically to test multi-field update functionality across various property combinations.";

  const initialTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: originalTitle,
        description: originalDescription,
        status: "pending",
        priority: "medium",
        due_date: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 days from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(initialTask);

  TestValidator.equals(
    "initial title matches",
    initialTask.title,
    originalTitle,
  );
  TestValidator.equals(
    "initial description matches",
    initialTask.description,
    originalDescription,
  );
  TestValidator.equals("initial status", initialTask.status, "pending");
  TestValidator.equals("initial priority", initialTask.priority, "medium");

  // Step 3: Test comprehensive multi-field update
  const updatedTitle =
    "Updated Task Title with More Detail for Comprehensive Testing";
  const updatedDescription =
    "This description has been modified to test the multi-field update functionality. The content is different from the original to ensure updates are properly applied.";
  const updatedPriority = RandomGenerator.pick([
    "low",
    "medium",
    "high",
  ] as const);
  const updatedDueDate = new Date(
    Date.now() + 60 * 24 * 60 * 60 * 1000,
  ).toISOString(); // 60 days from now

  const multiFieldUpdatedTask =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: initialTask.id,
      body: {
        title: updatedTitle,
        description: updatedDescription,
        priority: updatedPriority,
        due_date: updatedDueDate,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(multiFieldUpdatedTask);

  TestValidator.equals(
    "title updated correctly",
    multiFieldUpdatedTask.title,
    updatedTitle,
  );
  TestValidator.equals(
    "description updated correctly",
    multiFieldUpdatedTask.description,
    updatedDescription,
  );
  TestValidator.equals(
    "priority updated correctly",
    multiFieldUpdatedTask.priority,
    updatedPriority,
  );
  TestValidator.equals(
    "due date updated correctly",
    multiFieldUpdatedTask.due_date,
    updatedDueDate,
  );
  TestValidator.equals(
    "status unchanged during multi-field update",
    multiFieldUpdatedTask.status,
    "pending",
  ); // Status was not in update body, should remain unchanged

  // Step 4: Test status change with title update only
  const statusUpdate = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: initialTask.id,
      body: {
        title: "Task Updated to Completed Status",
        status: "completed",
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(statusUpdate);

  TestValidator.equals(
    "status changed to completed",
    statusUpdate.status,
    "completed",
  );
  await TestValidator.predicate(
    "completion date set after status change",
    statusUpdate.completed_at !== null &&
      statusUpdate.completed_at !== undefined,
  );
  TestValidator.equals(
    "priority preserved from previous update",
    statusUpdate.priority,
    updatedPriority,
  );
  TestValidator.equals(
    "due date preserved from previous update",
    statusUpdate.due_date,
    updatedDueDate,
  );

  // Step 5: Test maximum title length validation
  const maxLengthTitle = RandomGenerator.alphabets(200); // Exactly 200 characters
  const maxTitleTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: initialTask.id,
      body: {
        title: maxLengthTitle,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(maxTitleTask);

  TestValidator.equals(
    "task with maximum title length",
    maxTitleTask.title.length,
    200,
  );
  await TestValidator.predicate(
    "title content matches exactly",
    typia.is<string & tags.MaxLength<200>>(maxTitleTask.title),
  );

  // Step 6: Test description and priority clearing (null)
  const selectiveUpdateTask =
    await api.functional.todoApp.user.users.tasks.update(connection, {
      userId: user.id,
      taskId: initialTask.id,
      body: {
        description: null,
        priority: null,
      } satisfies ITodoAppTask.IUpdate,
    });
  typia.assert(selectiveUpdateTask);

  TestValidator.equals(
    "description cleared correctly",
    selectiveUpdateTask.description,
    null,
  );
  TestValidator.equals(
    "priority cleared correctly",
    selectiveUpdateTask.priority,
    null,
  );
  TestValidator.equals(
    "title preserved during selective update",
    selectiveUpdateTask.title,
    maxLengthTitle,
  );

  // Step 7: Test due date validation within 5-year constraint
  const validFutureDate = new Date(
    Date.now() + 3 * 365 * 24 * 60 * 60 * 1000,
  ).toISOString(); // ~3 years from now
  const validDueDateTask = await api.functional.todoApp.user.users.tasks.update(
    connection,
    {
      userId: user.id,
      taskId: initialTask.id,
      body: {
        due_date: validFutureDate,
      } satisfies ITodoAppTask.IUpdate,
    },
  );
  typia.assert(validDueDateTask);

  TestValidator.equals(
    "due date updated within valid range",
    validDueDateTask.due_date,
    validFutureDate,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test the simplified task creation workflow through POST /todoApp/user/tasks
 * endpoint. Validates that users can create personal todo items with essential
 * task properties including title with 200-character limits, optional
 * descriptions, priority level assignment, and optional due date configuration.
 * Ensures tasks are automatically associated with the authenticated user and
 * include proper server-side metadata like timestamps and unique identifiers.
 */
export async function test_api_simplified_task_creation(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for task ownership
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "securePassword123",
      href: "https://todo-app.example.com/register",
      referrer: "https://example.com/signup",
      name: RandomGenerator.name(2),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a basic task with minimal required fields
  const basicTitle = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 3,
    wordMax: 8,
  });
  const basicTask = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: basicTitle,
      status: "pending",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(basicTask);

  TestValidator.equals("basic task title matches", basicTask.title, basicTitle);
  TestValidator.equals(
    "basic task status is pending",
    basicTask.status,
    "pending",
  );
  TestValidator.predicate(
    "basic task created_at is set",
    basicTask.created_at !== undefined,
  );
  TestValidator.predicate("basic task id is uuid", basicTask.id !== undefined);
  TestValidator.predicate(
    "basic task user is set",
    basicTask.user !== undefined,
  );

  // Step 3: Create a task with all optional fields (due date, priority, description)
  const fullTask = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 5,
        wordMin: 2,
        wordMax: 6,
      }),
      description: RandomGenerator.content({
        paragraphs: 2,
        sentenceMin: 15,
        sentenceMax: 25,
        wordMin: 4,
        wordMax: 8,
      }),
      status: "completed",
      priority: RandomGenerator.pick([
        "none",
        "low",
        "medium",
        "high",
      ] as const),
      due_date: RandomGenerator.date(
        new Date(Date.now() + 86400000),
        86400000 * 30,
      ).toISOString(),
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(fullTask);

  TestValidator.predicate(
    "full task description is set",
    fullTask.description !== null && fullTask.description !== undefined,
  );
  TestValidator.predicate(
    "full task priority is set",
    fullTask.priority !== null && fullTask.priority !== undefined,
  );
  TestValidator.predicate(
    "full task due_date is set",
    fullTask.due_date !== null && fullTask.due_date !== undefined,
  );
  TestValidator.equals(
    "full task status is completed",
    fullTask.status,
    "completed",
  );
  TestValidator.predicate(
    "full task completed_at is set when status is completed",
    fullTask.completed_at !== undefined,
  );

  // Step 4: Test task with maximum title length (200 characters)
  const maxTitle = RandomGenerator.alphaNumeric(200);
  const longTask = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: maxTitle,
      status: "pending",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(longTask);

  TestValidator.equals(
    "long task title length is 200",
    longTask.title.length,
    200,
  );
  TestValidator.equals(
    "long task title matches input",
    longTask.title,
    maxTitle,
  );

  // Step 5: Test task with null optional fields
  const minimalTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 3,
          wordMax: 6,
        }),
        status: "pending",
        description: null,
        priority: null,
        due_date: null,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(minimalTask);

  TestValidator.equals(
    "minimal task description is null",
    minimalTask.description,
    null,
  );
  TestValidator.equals(
    "minimal task priority is null",
    minimalTask.priority,
    null,
  );
  TestValidator.equals(
    "minimal task due_date is null",
    minimalTask.due_date,
    null,
  );

  // Step 6: Verify user association
  TestValidator.equals(
    "task user ID matches authenticated user",
    basicTask.user.id,
    user.id,
  );
  TestValidator.equals(
    "task user email matches",
    basicTask.user.email,
    user.email,
  );
  TestValidator.predicate(
    "all tasks belong to same user",
    fullTask.user.id === user.id &&
      longTask.user.id === user.id &&
      minimalTask.user.id === user.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test minimal task creation using only required fields.
 *
 * This test validates that the API supports streamlined task creation with only
 * the required fields - title and status. It creates a new user, then creates a
 * minimal task without any optional fields (description, priority, due_date) to
 * ensure the system correctly handles the minimum required data and returns a
 * complete task object structure.
 *
 * The test verifies:
 *
 * 1. Task creation succeeds with only title and status
 * 2. Optional fields receive appropriate null/undefined values
 * 3. Response contains all expected task properties including timestamps
 * 4. The task is properly associated with the authenticated user
 * 5. Default values for optional fields are correct
 */
export async function test_api_task_creation_minimal_required(
  connection: api.IConnection,
) {
  // Step 1: Create user for authentication
  const userEmail: string = typia.random<string & tags.Format<"email">>();
  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: userEmail,
        password: "test1234",
        href: "https://example.com/join",
        referrer: "https://example.com",
      } satisfies ITodoAppUser.ICreate,
    },
  );
  typia.assert(user);

  // Step 2: Create minimal task with only required fields
  const taskTitle: string = RandomGenerator.paragraph({ sentences: 3 });
  const createdTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: taskTitle,
        status: "pending",
      } satisfies ITodoAppTask.ICreate,
    });
  typia.assert(createdTask);

  // Step 3: Validate task was created with expected properties
  TestValidator.equals("task has required title", createdTask.title, taskTitle);
  TestValidator.equals("task status is pending", createdTask.status, "pending");
  TestValidator.equals(
    "task has proper ID format",
    typeof createdTask.id,
    "string",
  );

  // Step 4: Verify optional fields are null/undefined as expected
  TestValidator.equals("description is null", createdTask.description, null);
  TestValidator.equals("priority is null", createdTask.priority, null);
  TestValidator.equals("due_date is null", createdTask.due_date, null);
  TestValidator.equals("completed_at is null", createdTask.completed_at, null);
  TestValidator.equals("deleted_at is null", createdTask.deleted_at, null);

  // Step 5: Validate user association
  TestValidator.equals("task has user info", createdTask.user.email, userEmail);
  TestValidator.equals("task user ID matches", createdTask.user.id, user.id);

  // Step 6: Validate timestamp fields
  TestValidator.predicate(
    "created_at is valid date",
    !isNaN(Date.parse(createdTask.created_at)),
  );
  TestValidator.predicate(
    "updated_at is valid date",
    !isNaN(Date.parse(createdTask.updated_at)),
  );
  TestValidator.notEquals(
    "timestamps differ",
    createdTask.created_at,
    createdTask.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation with explicit user_id specification to verify the optional
 * user_id parameter functionality. Validates that users can create tasks on
 * behalf of themselves through the optional user_id field while ensuring the
 * authentication system properly validates ownership and association.
 *
 * 1. Create a new user via the auth/join endpoint
 * 2. Create a task without explicitly providing user_id (default behavior)
 * 3. Create a task with explicit user_id parameter set to the authenticated user's
 *    ID
 * 4. Create a task with explicit user_id parameter set to null
 * 5. Validate that all tasks are properly assigned and the user relationship is
 *    maintained
 */
export async function test_api_task_creation_with_user_id_option(
  connection: api.IConnection,
) {
  // Create a new user account for testing
  const userData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "securePassword123",
    name: RandomGenerator.name(),
    href: "https://example.com/join",
    referrer: "https://example.com/home",
    ip: "192.168.1.1",
  } satisfies ITodoAppUser.ICreate;

  // Register new user and establish authentication
  const newUser: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userData },
  );
  typia.assert(newUser);

  // Test 1: Create task without explicit user_id (default behavior)
  const defaultTaskData = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
    status: "pending",
    priority: "medium",
    due_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
  } satisfies ITodoAppTask.ICreate;

  const defaultTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: defaultTaskData,
    });
  typia.assert(defaultTask);

  TestValidator.equals(
    "default task user ID matches authenticated user",
    defaultTask.user.id,
    newUser.id,
  );
  TestValidator.equals(
    "default task title matches input",
    defaultTask.title,
    defaultTaskData.title,
  );

  // Test 2: Create task with explicit user_id (set to authenticated user's ID)
  const explicitTaskData = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
    status: "pending",
    priority: "high",
    due_date: new Date(Date.now() + 172800000).toISOString(), // Day after tomorrow
    user_id: newUser.id,
  } satisfies ITodoAppTask.ICreate;

  const explicitTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: explicitTaskData,
    });
  typia.assert(explicitTask);

  TestValidator.equals(
    "explicit task user ID matches authenticated user",
    explicitTask.user.id,
    newUser.id,
  );
  TestValidator.equals(
    "explicit task title matches input",
    explicitTask.title,
    explicitTaskData.title,
  );

  // Test 3: Create task with explicit user_id set to null
  const nullUserTaskData = {
    title: RandomGenerator.paragraph({ sentences: 1 }),
    description: null,
    status: "pending",
    priority: "low",
    user_id: null,
  } satisfies ITodoAppTask.ICreate;

  const nullUserTask: ITodoAppTask =
    await api.functional.todoApp.user.tasks.create(connection, {
      body: nullUserTaskData,
    });
  typia.assert(nullUserTask);

  TestValidator.equals(
    "null user task user ID matches authenticated user",
    nullUserTask.user.id,
    newUser.id,
  );
  TestValidator.equals(
    "null user task title matches input",
    nullUserTask.title,
    nullUserTaskData.title,
  );
  TestValidator.equals(
    "null user task description is null",
    nullUserTask.description,
    null,
  );

  // Validate all tasks belong to the same authenticated user
  TestValidator.equals(
    "default task user ID matches new user",
    defaultTask.user.id,
    newUser.id,
  );
  TestValidator.equals(
    "explicit task user ID matches new user",
    explicitTask.user.id,
    newUser.id,
  );
  TestValidator.equals(
    "null user task user ID matches new user",
    nullUserTask.user.id,
    newUser.id,
  );

  // Verify user summary data consistency across all tasks
  TestValidator.equals(
    "default task user email matches new user",
    defaultTask.user.email,
    newUser.email,
  );
  TestValidator.equals(
    "explicit task user email matches new user",
    explicitTask.user.email,
    newUser.email,
  );
  TestValidator.equals(
    "null user task user email matches new user",
    nullUserTask.user.email,
    newUser.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_task_completion_workflow_with_deletion(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for task management
  const email = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password,
      href: "https://example.com/todo-app",
      referrer: "https://example.com/home",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a new task for the authenticated user
  const taskData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 2, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 3,
      sentenceMax: 5,
    }),
    status: "pending",
    priority: RandomGenerator.pick(["none", "low", "medium", "high"] as const),
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 1 week from now
  } satisfies ITodoAppTask.ICreate;

  const task = await api.functional.todoApp.user.tasks.create(connection, {
    body: taskData,
  });
  typia.assert(task);

  // Step 3: Verify the task exists in the user's task list
  const searchResult = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResult);

  // Step 4: Validate the created task appears in search results
  TestValidator.predicate(
    "created task appears in user's task list",
    searchResult.data.some((t) => t.id === task.id && t.title === task.title),
  );

  TestValidator.equals("task has correct owner", task.user.id, user.id);
  TestValidator.equals("task title matches", task.title, taskData.title);
  TestValidator.equals(
    "task description matches",
    task.description,
    taskData.description,
  );
  TestValidator.equals("task status is pending", task.status, "pending");
  TestValidator.predicate(
    "task priority is valid",
    ["none", "low", "medium", "high"].includes(task.priority || "medium"),
  );

  // Step 5: Delete the task permanently
  const deletedTask = await api.functional.todoApp.user.tasks.erase(
    connection,
    {
      taskId: task.id,
    },
  );
  typia.assert(deletedTask);

  TestValidator.equals(
    "deleted task is the same as created task",
    deletedTask.id,
    task.id,
  );
  TestValidator.equals(
    "deleted task retains title",
    deletedTask.title,
    task.title,
  );

  // Step 6: Verify task no longer appears in user's task list
  const verificationSearch = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(verificationSearch);

  TestValidator.predicate(
    "task is completely removed from user's task list",
    !verificationSearch.data.some((t) => t.id === task.id),
  );

  TestValidator.equals(
    "task count decreased after deletion",
    verificationSearch.data.length,
    searchResult.data.length - 1,
  );
  TestValidator.predicate(
    "tasks have valid status",
    verificationSearch.data.every(
      (t) => t.status === "pending" || t.status === "completed",
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation cycle with deletion functionality.
 *
 * This test validates the complete lifecycle of todo tasks through creation and
 * deletion, simulating natural user behavior where tasks are created and later
 * removed when they become unnecessary or were created by mistake. The workflow
 * tests authentication, task creation, verification of task existence, and
 * final deletion operations.
 *
 * The test follows this sequence:
 *
 * 1. User registration and authentication
 * 2. Task creation with comprehensive data
 * 3. Task verification using search functionality
 * 4. Task deletion operation
 * 5. Confirmation that tasks are properly removed
 *
 * @param connection API connection for test execution
 */
export async function test_api_task_creation_cycle_with_deletion(
  connection: api.IConnection,
): Promise<void> {
  // Initialize user authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "12345678",
      href: "https://example.com/register",
      referrer: "https://example.com/home",
      name: RandomGenerator.name(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Create initial task with comprehensive data
  const taskData = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.paragraph({
      sentences: 4,
      wordMin: 5,
      wordMax: 10,
    }),
    status: "pending",
    priority: "medium",
    due_date: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7 days from now
  } satisfies ITodoAppTask.ICreate;

  const createdTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: taskData,
    },
  );
  typia.assert(createdTask);

  // Verify task was created successfully
  TestValidator.equals("task creation success", createdTask.status, "pending");
  TestValidator.equals("task title matches", createdTask.title, taskData.title);
  TestValidator.equals("task priority set", createdTask.priority, "medium");

  // Search for the created task to confirm it exists in the system
  const searchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        search: taskData.title,
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResults);

  // Verify the created task appears in search results
  TestValidator.predicate(
    "task found in search",
    searchResults.data.some((task) => task.id === createdTask.id),
  );
  TestValidator.equals("search returns tasks", searchResults.data.length, 1);

  // Delete the task permanently
  const deletedTask = await api.functional.todoApp.user.tasks.erase(
    connection,
    {
      taskId: createdTask.id,
    },
  );
  typia.assert(deletedTask);

  // Confirm task deletion was successful
  TestValidator.equals(
    "deleted task has same id",
    deletedTask.id,
    createdTask.id,
  );

  // Verify task no longer appears in search results
  const postDeletionResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        search: taskData.title,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(postDeletionResults);

  TestValidator.equals(
    "task no longer exists",
    postDeletionResults.data.length,
    0,
  );

  // Test creating multiple tasks and deleting one
  const task1 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: "First Task",
      status: "pending",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task1);

  const task2 = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: "Second Task",
      status: "pending",
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task2);

  // Delete only the first task
  await api.functional.todoApp.user.tasks.erase(connection, {
    taskId: task1.id,
  });

  // Verify only the second task remains
  const remainingTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(remainingTasks);

  TestValidator.equals("only one task remains", remainingTasks.data.length, 1);
  TestValidator.equals(
    "remaining task is second task",
    remainingTasks.data[0].title,
    "Second Task",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test dated task workflow including creation with due dates, task completion
 * tracking, and final deletion. Validates complete dated task management where
 * users set due dates, track progress, and clean up completed tasks. Simulates
 * realistic productivity workflows where time-sensitive tasks go through full
 * lifecycle management.
 *
 * 1. Create a new user account for task management
 * 2. Create a task with a due date for time-sensitive workflow testing
 * 3. Track task status and verify due date compliance
 * 4. Update task to completed status
 * 5. Verify task completion tracking
 * 6. Permanently delete the task from the system
 * 7. Validate the complete dated task lifecycle from creation to deletion
 */
export async function test_api_dated_task_workflow_completion(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for task management
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePass123",
      name: RandomGenerator.name(),
      href: "https://todoapp.example.com/join",
      referrer: "https://todoapp.example.com/home",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a task with a due date for time-sensitive workflow testing
  const dueDate = new Date();
  dueDate.setDate(dueDate.getDate() + 7); // Due in 7 days

  const task = await api.functional.todoApp.user.tasks.create(connection, {
    body: {
      title: RandomGenerator.paragraph({
        sentences: 3,
        wordMin: 5,
        wordMax: 10,
      }),
      description: RandomGenerator.content({
        paragraphs: 2,
        sentenceMin: 5,
        sentenceMax: 10,
      }),
      status: "pending",
      priority: RandomGenerator.pick([
        "none",
        "low",
        "medium",
        "high",
      ] as const),
      due_date: dueDate.toISOString(),
    } satisfies ITodoAppTask.ICreate,
  });
  typia.assert(task);

  // Verify task creation and due date
  TestValidator.equals("task title matches", task.title, task.title);
  TestValidator.equals("task status is pending", task.status, "pending");
  TestValidator.predicate(
    "task has due date set",
    task.due_date !== null && task.due_date !== undefined,
  );

  // Step 3: Track task status and verify due date compliance
  const searchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
        due_before: new Date(Date.now() + 86400000 * 10).toISOString(), // Due within next 10 days
        limit: 10,
        page: 1,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResults);

  // Verify task appears in filtered search results
  TestValidator.predicate(
    "task found in pending tasks with due date filter",
    searchResults.data.some((t) => t.id === task.id),
  );

  // Step 4: Update task to completed status (simulate task completion)
  const completedTaskUpdate = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Completed: " + task.title,
        description: task.description,
        status: "completed",
        priority: task.priority,
        due_date: task.due_date,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTaskUpdate);

  // Step 5: Verify task completion tracking
  const completedSearchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "completed",
        limit: 10,
        page: 1,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(completedSearchResults);

  TestValidator.predicate(
    "completed task appears in completed tasks list",
    completedSearchResults.data.some((t) => t.id === completedTaskUpdate.id),
  );

  // Step 6: Permanently delete the task from the system
  const deletedTask = await api.functional.todoApp.user.tasks.erase(
    connection,
    {
      taskId: completedTaskUpdate.id,
    },
  );
  typia.assert(deletedTask);

  // Verify task was deleted by checking it no longer appears in search results
  const searchAfterDeletion = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        search: completedTaskUpdate.title,
        limit: 10,
        page: 1,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchAfterDeletion);

  TestValidator.equals(
    "deleted task not found in search results",
    searchAfterDeletion.data.some((t) => t.id === completedTaskUpdate.id),
    false,
  );

  // Step 7: Validate the complete dated task lifecycle from creation to deletion
  TestValidator.predicate(
    "task had valid due date format",
    task.due_date !== null &&
      task.due_date !== undefined &&
      /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])/.test(task.due_date),
  );
  TestValidator.predicate(
    "deleted task matches original task ID",
    deletedTask.id === completedTaskUpdate.id,
  );
  TestValidator.predicate(
    "task lifecycle completed successfully",
    task.id !== null &&
      task.status === "pending" &&
      deletedTask.id === task.id &&
      deletedTask.status === "completed",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test efficient task cleanup patterns where users delete completed tasks to
 * maintain organized todo lists. Validates that users can effectively manage
 * task overflow by removing finished items while maintaining active tasks.
 * Simulates natural productivity habits of cleaning up completed work to
 * maintain focus on pending tasks.
 */
export async function test_api_task_cleanup_after_completion(
  connection: api.IConnection,
) {
  // Step 1: User registration and authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePassword123",
      name: RandomGenerator.name(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com/landing",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create multiple tasks with different statuses
  const pendingTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Review project documentation",
        description: "Go through the latest project specs and requirements",
        status: "pending",
        priority: "high",
        due_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask1);

  const pendingTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Schedule team meeting",
        description: "Coordinate with team members for next week",
        status: "pending",
        priority: "medium",
        due_date: new Date(Date.now() + 172800000).toISOString(), // Day after tomorrow
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask2);

  const completedTask1 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Update project timeline",
        description: "Completed the timeline adjustment for Q4 deliverables",
        status: "completed",
        priority: "medium",
        due_date: new Date(Date.now() - 86400000).toISOString(), // Yesterday
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask1);

  const completedTask2 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Send status report",
        description: "Emailed weekly status update to stakeholders",
        status: "completed",
        priority: "low",
        due_date: new Date(Date.now() - 172800000).toISOString(), // Two days ago
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask2);

  const pendingTask3 = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Prepare presentation slides",
        description: "Create slides for the upcoming client presentation",
        status: "pending",
        priority: "high",
        due_date: new Date(Date.now() + 259200000).toISOString(), // Three days from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(pendingTask3);

  // Step 3: Verify initial task setup
  const allTasksResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(allTasksResponse);

  TestValidator.equals(
    "total initial tasks",
    allTasksResponse.pagination.records,
    5,
  );

  // Verify pending tasks exist
  const pendingTasksResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pendingTasksResponse);

  TestValidator.equals(
    "pending tasks count",
    pendingTasksResponse.pagination.records,
    3,
  );

  // Verify completed tasks exist
  const completedTasksResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "completed",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(completedTasksResponse);

  TestValidator.equals(
    "completed tasks count",
    completedTasksResponse.pagination.records,
    2,
  );

  // Step 4: Delete completed tasks to clean up
  const deletedTask1 = await api.functional.todoApp.user.tasks.erase(
    connection,
    {
      taskId: completedTask1.id,
    },
  );
  typia.assert(deletedTask1);

  TestValidator.equals(
    "deleted task title matches",
    deletedTask1.title,
    completedTask1.title,
  );

  const deletedTask2 = await api.functional.todoApp.user.tasks.erase(
    connection,
    {
      taskId: completedTask2.id,
    },
  );
  typia.assert(deletedTask2);

  TestValidator.equals(
    "deleted task title matches",
    deletedTask2.title,
    completedTask2.title,
  );

  // Step 5: Verify cleanup operation
  const afterCleanupResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(afterCleanupResponse);

  TestValidator.equals(
    "tasks after cleanup",
    afterCleanupResponse.pagination.records,
    3,
  );

  // Verify only pending tasks remain
  const remainingPending = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(remainingPending);

  TestValidator.equals(
    "all remaining are pending",
    remainingPending.pagination.records,
    3,
  );

  // Verify no completed tasks remain
  const remainingCompleted = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "completed",
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(remainingCompleted);

  TestValidator.equals(
    "no completed tasks remain",
    remainingCompleted.pagination.records,
    0,
  );

  // Step 6: Verify deleted tasks are no longer accessible
  await TestValidator.error("cannot delete already deleted task", async () => {
    await api.functional.todoApp.user.tasks.erase(connection, {
      taskId: completedTask1.id,
    });
  });

  // Verify pending tasks are unaffected by cleanup
  const pendingTaskIds = remainingPending.data.map((task) => task.id);
  const originalPendingIds = [
    pendingTask1.id,
    pendingTask2.id,
    pendingTask3.id,
  ];

  TestValidator.equals(
    "pending tasks preserved",
    pendingTaskIds,
    originalPendingIds,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test creation of urgent high-priority tasks for immediate attention items.
 *
 * Validates the complete urgent task workflow including priority assignment,
 * due date setting, and content organization for time-sensitive work items.
 * Simulates scenarios where users need to quickly capture urgent tasks with
 * full context including priority and completion tracking.
 *
 * Test Steps:
 *
 * 1. Create authenticated user account
 * 2. Create urgent task with high priority and due date
 * 3. Create multiple urgent tasks with varying priorities
 * 4. Verify task properties and organization
 * 5. Test complete workflow for urgent task management
 */
export async function test_api_urgent_task_creation(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user account
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "SecurePass123!",
      name: RandomGenerator.name(),
      href: "https://todoapp.example.com/signup",
      referrer: "https://todoapp.example.com/",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create urgent task with high priority and due date
  const urgentDueDate = new Date(
    Date.now() + 24 * 60 * 60 * 1000,
  ).toISOString(); // Tomorrow
  const urgentTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Complete urgent project deliverable",
        description:
          "Finalize and submit the quarterly report to stakeholders by end of business day",
        status: "pending",
        priority: "high",
        due_date: urgentDueDate,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(urgentTask);

  // Verify urgent task properties
  TestValidator.equals(
    "urgent task has high priority",
    urgentTask.priority,
    "high",
  );
  TestValidator.equals(
    "urgent task status is pending",
    urgentTask.status,
    "pending",
  );
  TestValidator.predicate(
    "urgent task has due date",
    urgentTask.due_date !== null && urgentTask.due_date !== undefined,
  );
  TestValidator.equals(
    "urgent task title matches",
    urgentTask.title,
    "Complete urgent project deliverable",
  );
  TestValidator.equals("urgent task user matches", urgentTask.user.id, user.id);

  // Step 3: Create multiple urgent tasks with varying priorities
  const mediumUrgentTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Review client feedback",
        description:
          "Address urgent client concerns about the latest feature release",
        status: "pending",
        priority: "medium",
        due_date: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(), // Day after tomorrow
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(mediumUrgentTask);

  const lowPriorityTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Update documentation",
        description: "Add new API endpoints to the technical documentation",
        status: "pending",
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(lowPriorityTask);

  const criticalTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Fix production bug",
        description:
          "Critical issue affecting user login - needs immediate attention",
        status: "pending",
        priority: "high",
        due_date: new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString(), // 4 hours from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(criticalTask);

  // Step 4: Verify task organization and properties
  TestValidator.equals(
    "medium urgent task has medium priority",
    mediumUrgentTask.priority,
    "medium",
  );
  TestValidator.equals(
    "low priority task has low priority",
    lowPriorityTask.priority,
    "low",
  );
  TestValidator.equals(
    "critical task has high priority",
    criticalTask.priority,
    "high",
  );

  TestValidator.predicate(
    "low priority task has no due date",
    lowPriorityTask.due_date === null || lowPriorityTask.due_date === undefined,
  );
  TestValidator.predicate(
    "medium urgent task has due date",
    mediumUrgentTask.due_date !== null &&
      mediumUrgentTask.due_date !== undefined,
  );
  TestValidator.predicate(
    "critical task has due date",
    criticalTask.due_date !== null && criticalTask.due_date !== undefined,
  );

  // Verify all tasks belong to the same user
  TestValidator.equals("urgent task user matches", urgentTask.user.id, user.id);
  TestValidator.equals(
    "medium urgent task user matches",
    mediumUrgentTask.user.id,
    user.id,
  );
  TestValidator.equals(
    "low priority task user matches",
    lowPriorityTask.user.id,
    user.id,
  );
  TestValidator.equals(
    "critical task user matches",
    criticalTask.user.id,
    user.id,
  );

  // Verify task creation timestamps
  TestValidator.predicate(
    "tasks have creation timestamps",
    urgentTask.created_at !== null &&
      mediumUrgentTask.created_at !== null &&
      lowPriorityTask.created_at !== null &&
      criticalTask.created_at !== null,
  );

  // Step 5: Test complete workflow validation
  TestValidator.predicate(
    "all tasks are in pending status",
    urgentTask.status === "pending" &&
      mediumUrgentTask.status === "pending" &&
      lowPriorityTask.status === "pending" &&
      criticalTask.status === "pending",
  );

  // Verify task descriptions are properly stored
  TestValidator.predicate(
    "urgent task has description",
    urgentTask.description !== null && urgentTask.description !== undefined,
  );
  TestValidator.predicate(
    "critical task has description",
    criticalTask.description !== null && criticalTask.description !== undefined,
  );

  TestValidator.equals(
    "all tasks have unique IDs",
    new Set([
      urgentTask.id,
      mediumUrgentTask.id,
      lowPriorityTask.id,
      criticalTask.id,
    ]).size,
    4,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test rapid task creation for simple todo items that users need to capture
 * quickly. Focuses on minimal required fields with optional enhancements to
 * test the app's quick capture capabilities. Validates efficient workflow where
 * users can instantly record tasks without extensive configuration while
 * maintaining full functionality.
 *
 * 1. Create user account for authentication
 * 2. Test minimal task creation (title only)
 * 3. Test task creation with optional description
 * 4. Test task creation with priority setting
 * 5. Test task creation with due date
 * 6. Test task creation with completed status
 * 7. Verify task appears in search results after creation
 * 8. Test various combinations of optional fields
 */
export async function test_api_quick_task_capture(connection: api.IConnection) {
  // Step 1: Create user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      name: RandomGenerator.name(),
      href: "https://example.com/join",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Test minimal task creation (title only)
  const minimalTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Quick task capture test",
        status: "pending",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(minimalTask);
  TestValidator.equals(
    "minimal task title",
    minimalTask.title,
    "Quick task capture test",
  );
  TestValidator.equals("minimal task status", minimalTask.status, "pending");

  // Step 3: Test task creation with optional description
  const taskWithDescription = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Task with detailed description",
        description:
          "This task has additional context for better understanding",
        status: "pending",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskWithDescription);
  TestValidator.equals(
    "task with description title",
    taskWithDescription.title,
    "Task with detailed description",
  );
  TestValidator.equals(
    "task description",
    taskWithDescription.description,
    "This task has additional context for better understanding",
  );

  // Step 4: Test task creation with priority setting
  const priorityTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "High priority task",
        status: "pending",
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(priorityTask);
  TestValidator.equals(
    "priority task title",
    priorityTask.title,
    "High priority task",
  );
  TestValidator.equals("priority level", priorityTask.priority, "high");

  // Step 5: Test task creation with due date
  const dueDateTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Task with deadline",
        status: "pending",
        due_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(dueDateTask);
  TestValidator.equals(
    "due date task title",
    dueDateTask.title,
    "Task with deadline",
  );
  TestValidator.predicate("due date is set", dueDateTask.due_date !== null);

  // Step 6: Test task creation with completed status
  const completedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Already completed task",
        status: "completed",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask);
  TestValidator.equals(
    "completed task title",
    completedTask.title,
    "Already completed task",
  );
  TestValidator.equals("completed status", completedTask.status, "completed");
  TestValidator.predicate(
    "completed at timestamp is set",
    completedTask.completed_at !== null,
  );

  // Step 7: Verify task appears in search results after creation
  const searchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        search: "capture",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResults);
  TestValidator.predicate(
    "search results contain created task",
    searchResults.data.length > 0,
  );
  TestValidator.predicate(
    "search found capture task",
    searchResults.data.some((task) => task.title.includes("capture")),
  );

  // Step 8: Test various combinations of optional fields
  const complexTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Complex task with all options",
        description:
          "This task includes description, high priority, and due date",
        status: "pending",
        priority: "high",
        due_date: new Date(Date.now() + 172800000).toISOString(), // 2 days from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(complexTask);
  TestValidator.equals(
    "complex task title",
    complexTask.title,
    "Complex task with all options",
  );
  TestValidator.equals(
    "complex task description",
    complexTask.description,
    "This task includes description, high priority, and due date",
  );
  TestValidator.equals("complex task priority", complexTask.priority, "high");
  TestValidator.predicate(
    "complex task due date is set",
    complexTask.due_date !== null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test recurring task creation patterns to ensure consistent todo list
 * management
 *
 * This test simulates real-world usage patterns where users repeatedly create
 * similar tasks for daily work tracking. It validates the consistency and
 * reliability of task creation across multiple iterations, testing different
 * task configurations including titles, descriptions, priorities, and due
 * dates.
 */
export async function test_api_recurring_task_setup(
  connection: api.IConnection,
) {
  // Step 1: Create authenticated user for recurring task pattern testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "1234",
      name: RandomGenerator.name(),
      href: "https://example.com/todoApp",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Test recurring daily task creation patterns
  const dailyTaskTitles = [
    "Check morning emails",
    "Review daily schedule",
    "Update project status",
    "Team standup meeting",
  ];

  const createdTasks: ITodoAppTask[] = [];

  // Create multiple tasks simulating daily work routine
  for (let day = 1; day <= 5; day++) {
    const taskTitle = RandomGenerator.pick(dailyTaskTitles);
    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: `${taskTitle} - Day ${day}`,
        description: `Daily task for workflow completion - Day ${day}`,
        status: "pending",
        priority: RandomGenerator.pick([
          "none",
          "low",
          "medium",
          "high",
        ] as const),
      } satisfies ITodoAppTask.ICreate,
    });
    typia.assert(task);
    createdTasks.push(task);
  }

  // Step 3: Track task creation patterns and verify consistency
  const searchResult = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
        order_by: "created_at",
        order_direction: "desc",
        limit: 10,
        due_before: "2025-12-31T23:59:59Z", // Add realistic due date filter
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResult);

  // Step 4: Validate consistency across iterations
  TestValidator.predicate(
    "all tasks have consistent user ownership",
    searchResult.data.every(
      (task: ITodoAppTask.ISummary) => task.user.id === user.id,
    ),
  );

  TestValidator.predicate(
    "all pending tasks created in proper order",
    searchResult.data.length >= 5,
  );

  // Validate specific task properties
  const sampleTask = searchResult.data[0];
  TestValidator.equals("task status is pending", sampleTask.status, "pending");
  TestValidator.predicate(
    "task title contains day identifier",
    sampleTask.title.includes("Day"),
  );
  TestValidator.predicate(
    "priority is valid value",
    ["none", "low", "medium", "high"].includes(sampleTask.priority || "none"),
  );

  // Step 5: Simulate recurring pattern verification
  const recurringTasksCreated = createdTasks.filter((task) =>
    task.title.includes("Day"),
  );

  TestValidator.equals(
    "correct number of recurring tasks created",
    recurringTasksCreated.length,
    5,
  );

  TestValidator.predicate(
    "tasks have unique identifiers",
    new Set(recurringTasksCreated.map((t) => t.id)).size ===
      recurringTasksCreated.length,
  );

  TestValidator.predicate(
    "tasks have consistent creation pattern",
    recurringTasksCreated.every(
      (task) => task.created_at !== null && task.created_at !== undefined,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation with varied priority levels to validate the app's
 * prioritization capabilities. Creates tasks across all priority levels from
 * none to high to test comprehensive priority management. Validates that users
 * can effectively organize work by urgency and importance using the app's
 * priority system.
 *
 * Test workflow:
 *
 * 1. Create a new user account for testing
 * 2. Create tasks with different priority levels (none, low, medium, high)
 * 3. Verify that each task maintains its correct priority assignment
 * 4. Use the task listing endpoint to filter and verify priority-based queries
 * 5. Ensure the priority system works correctly for all supported levels
 */
export async function test_api_task_prioritization_workflow(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Create user account for testing
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "TestPassword123",
      name: RandomGenerator.name(),
      href: "https://example.com/todo-app",
      referrer: "https://example.com/todo-app",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create tasks with different priority levels
  const priorityLevels = ["none", "low", "medium", "high"] as const;
  const tasks: ITodoAppTask[] = [];

  // Create one task for each priority level
  for (const priority of priorityLevels) {
    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: `Test task with ${priority} priority`,
        description: `This task has ${priority} priority level for validation testing`,
        status: "pending",
        priority: priority,
      } satisfies ITodoAppTask.ICreate,
    });
    typia.assert(task);
    tasks.push(task);
  }

  // Step 3: Verify created tasks have correct priority assignments
  TestValidator.equals(
    "priority level count should match",
    tasks.length,
    priorityLevels.length,
  );

  for (let i = 0; i < tasks.length; i++) {
    TestValidator.equals(
      `task ${i + 1} has expected priority`,
      tasks[i].priority,
      priorityLevels[i],
    );
    TestValidator.equals(
      `task ${i + 1} has correct status`,
      tasks[i].status,
      "pending",
    );
  }

  // Step 4: Test task listing with priority filtering
  const allTasksResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        priority: undefined,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(allTasksResponse);

  // Verify at least our created tasks are returned
  TestValidator.predicate(
    "task count is reasonable",
    allTasksResponse.data.length >= priorityLevels.length,
  );

  // Test filtering by each priority level
  for (const priority of priorityLevels) {
    const filteredResponse = await api.functional.todoApp.user.tasks.index(
      connection,
      {
        body: {
          priority: priority,
        } satisfies ITodoAppTask.IRequest,
      },
    );
    typia.assert(filteredResponse);

    // Verify all tasks in filtered response have the requested priority
    TestValidator.predicate(
      `filtered tasks have ${priority} priority`,
      filteredResponse.data.every((task) => task.priority === priority),
    );

    // Verify we have at least one task for the requested priority
    TestValidator.predicate(
      `has tasks with ${priority} priority`,
      filteredResponse.data.length >= 1,
    );
  }

  // Step 5: Verify task page summary includes priority information
  const summaryResponse = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        limit: 10,
        order_by: "priority",
        order_direction: "asc",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(summaryResponse);

  // Verify pagination structure
  TestValidator.predicate(
    "pagination is valid",
    summaryResponse.pagination.limit <= 10,
  );
  TestValidator.equals(
    "pagination limit matches request",
    summaryResponse.pagination.limit,
    Math.min(summaryResponse.data.length, 10),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task creation followed by immediate completion to validate the complete
 * create-to-complete workflow. Validates that tasks can be created with
 * appropriate status and that the full lifecycle is properly managed. Tests the
 * natural progression from task creation through completion tracking with
 * comprehensive search validation.
 */
export async function test_api_task_completion_flow_integration(
  connection: api.IConnection,
) {
  // Step 1: Create a new user account for authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "securePassword123",
      name: RandomGenerator.name(),
      href: "https://todoapp.example.com/",
      referrer: "https://example.com/",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create a new todo task with pending status
  const taskTitle = RandomGenerator.paragraph({ sentences: 3 });
  const taskDescription = RandomGenerator.paragraph({ sentences: 5 });
  const dueDate = new Date(Date.now() + 86400000).toISOString(); // Tomorrow

  const createdTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: taskTitle,
        description: taskDescription,
        status: "pending",
        priority: "medium",
        due_date: dueDate,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(createdTask);

  // Step 3: Verify the created task has correct initial properties
  TestValidator.equals("task title matches", createdTask.title, taskTitle);
  TestValidator.equals(
    "task description matches",
    createdTask.description,
    taskDescription,
  );
  TestValidator.equals("task status is pending", createdTask.status, "pending");
  TestValidator.equals(
    "task priority is medium",
    createdTask.priority,
    "medium",
  );
  TestValidator.equals("task due date matches", createdTask.due_date, dueDate);
  TestValidator.predicate(
    "task has user association",
    createdTask.user.id === user.id,
  );
  TestValidator.predicate(
    "task created_at is set",
    createdTask.created_at !== null,
  );
  TestValidator.predicate(
    "task updated_at matches created_at initially",
    createdTask.updated_at === createdTask.created_at,
  );
  TestValidator.predicate(
    "task completed_at is null initially",
    createdTask.completed_at === null,
  );

  // Step 4: Search for the task to verify it appears in task listings
  const searchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        search: taskTitle.split(" ")[0], // Search for first word of title
        page: 1,
        limit: 10,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResults);

  // Verify search returns our task
  const foundTask = searchResults.data.find(
    (task) => task.id === createdTask.id,
  );
  TestValidator.predicate(
    "task found in search results",
    foundTask !== undefined,
  );
  TestValidator.equals(
    "search result task title matches",
    foundTask!.title,
    createdTask.title,
  );
  TestValidator.equals(
    "search result task status matches",
    foundTask!.status,
    createdTask.status,
  );

  // Step 5: Filter by status to verify pending tasks are listed correctly
  const pendingTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pendingTasks);

  // Verify our task appears in pending tasks list
  const pendingTask = pendingTasks.data.find(
    (task) => task.id === createdTask.id,
  );
  TestValidator.predicate(
    "task appears in pending tasks list",
    pendingTask !== undefined,
  );

  // Step 6: Create another completed task to test search filtering
  const completedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        status: "completed",
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask);

  // Step 7: Verify completed task appears in completed status filter
  const completedTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "completed",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(completedTasks);

  const foundCompletedTask = completedTasks.data.find(
    (task) => task.id === completedTask.id,
  );
  TestValidator.predicate(
    "completed task appears in completed filter",
    foundCompletedTask !== undefined,
  );
  TestValidator.equals(
    "completed task status is correct",
    foundCompletedTask!.status,
    "completed",
  );

  // Step 8: Test priority filtering with the created tasks
  const mediumPriorityTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        priority: "medium",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(mediumPriorityTasks);

  const foundMediumTask = mediumPriorityTasks.data.find(
    (task) => task.id === createdTask.id,
  );
  TestValidator.predicate(
    "medium priority task appears in medium filter",
    foundMediumTask !== undefined,
  );
  TestValidator.equals(
    "medium priority matches",
    foundMediumTask!.priority,
    "medium",
  );

  // Step 9: Verify pagination works correctly
  TestValidator.predicate(
    "pagination object exists",
    mediumPriorityTasks.pagination !== undefined,
  );
  TestValidator.predicate(
    "pagination current page is valid",
    mediumPriorityTasks.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is valid",
    mediumPriorityTasks.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "pagination records count is valid",
    mediumPriorityTasks.pagination.records >= 0,
  );

  // Step 10: Test due date filtering
  const tomorrowTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        due_before: new Date(Date.now() + 172800000).toISOString(), // Due before day after tomorrow
        due_after: new Date(Date.now()).toISOString(), // Due after now
        page: 1,
        limit: 100,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(tomorrowTasks);

  const dueDateTask = tomorrowTasks.data.find(
    (task) => task.id === createdTask.id,
  );
  TestValidator.predicate(
    "task with due date appears in date range filter",
    dueDateTask !== undefined,
  );

  // Step 11: Create a completed task with completion timestamp to test completion workflow
  const taskToComplete = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: "Task for completion workflow testing",
        description:
          "This task will test the complete workflow from creation to completion",
        status: "pending",
        priority: "high",
        due_date: new Date(Date.now() + 43200000).toISOString(), // 12 hours from now
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskToComplete);

  // Verify the completion workflow - task starts as pending
  TestValidator.equals(
    "initial task status is pending",
    taskToComplete.status,
    "pending",
  );
  TestValidator.predicate(
    "initial completion timestamp is null",
    taskToComplete.completed_at === null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test priority-focused task discovery and organization to validate the app's
 * prioritization system effectiveness. Creates tasks with all priority levels
 * and tests search/filtering by priority to ensure users can effectively focus
 * on urgent work. Validates that high-priority tasks are easily discoverable
 * and manageable within the user's todo list organization workflow.
 */
export async function test_api_priority_based_task_organization(
  connection: api.IConnection,
) {
  // Step 1: Register as a user
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
      href: typia.random<string & tags.MinLength<10> & tags.Format<"uri">>(),
      referrer: typia.random<
        string & tags.MinLength<10> & tags.Format<"uri">
      >(),
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Create tasks with different priority levels
  const priorities = ["none", "low", "medium", "high"] as const;
  const tasks = await ArrayUtil.asyncRepeat(12, async (index) => {
    const priority = priorities[index % 4];
    const taskData = {
      title: `Priority ${priority} task #${index + 1}`,
      description: `Task description for ${priority} priority item`,
      status: RandomGenerator.pick(["pending", "completed"]),
    } satisfies ITodoAppTask.ICreate;

    // Handle 'none' priority which should be null/undefined
    if (priority !== "none") {
      (taskData as any).priority = priority;
    }

    return await api.functional.todoApp.user.tasks.create(connection, {
      body: taskData,
    });
  });
  typia.assert(tasks);

  // Step 3: Test filtering by high priority
  const highPriorityTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        priority: "high",
        order_by: "priority",
        order_direction: "desc",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(highPriorityTasks);

