import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTask";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test comprehensive task analytics across bulk operations to validate data
 * aggregation and insights generation.
 *
 * This test creates various types of tasks with different priorities, statuses,
 * and due dates to analyze bulk operations and verify accurate statistics about
 * completion rates, priority distributions, and time-based trends. Validates
 * that the todo app's API can handle bulk task management and provide
 * meaningful insights for enhanced productivity management.
 *
 * 1. Create user account and authenticate
 * 2. Generate bulk task dataset with varied properties
 * 3. Test completion rate statistics
 * 4. Validate priority distribution analytics
 * 5. Analyze time-based trends
 * 6. Test search and filtering capabilities
 * 7. Verify pagination with bulk data
 * 8. Test task status analytics
 * 9. Validate priority-based insights
 * 10. Test due date analytics
 */
export async function test_api_bulk_task_analysis_and_insights(
  connection: api.IConnection,
) {
  // Step 1: Create user account and authenticate
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "password123",
      name: RandomGenerator.name(),
      href: "https://example.com",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Generate bulk task dataset with varied properties
  const tasks = await ArrayUtil.asyncRepeat(50, async (idx) => {
    const priorities = ["none", "low", "medium", "high"] as const;
    const statuses = ["pending", "completed"] as const;

    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 8,
        }),
        description: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 5,
          wordMax: 10,
        }),
        status: RandomGenerator.pick(statuses),
        priority: RandomGenerator.pick(priorities),
        due_date:
          Math.random() < 0.7
            ? new Date(
                Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000,
              ).toISOString()
            : null,
      } satisfies ITodoAppTask.ICreate,
    });
    typia.assert(task);
    return task;
  });

  // Step 3: Test completion rate statistics
  const completedCount = tasks.filter((t) => t.status === "completed").length;
  const pendingCount = tasks.filter((t) => t.status === "pending").length;
  const totalCount = tasks.length;

  TestValidator.predicate(
    "completion rate should be greater than 0",
    completedCount > 0 && completedCount < totalCount,
  );
  TestValidator.predicate("pending items should exist", pendingCount > 0);

  // Step 4: Validate priority distribution analytics
  const priorityStats = {
    none: tasks.filter((t) => t.priority === "none" || t.priority === null)
      .length,
    low: tasks.filter((t) => t.priority === "low").length,
    medium: tasks.filter((t) => t.priority === "medium").length,
    high: tasks.filter((t) => t.priority === "high").length,
  };

  TestValidator.predicate(
    "priority distribution should cover multiple levels",
    priorityStats.none +
      priorityStats.low +
      priorityStats.medium +
      priorityStats.high >
      0,
  );

  // Step 5: Analyze time-based trends
  const dueTasks = tasks.filter(
    (t) => t.due_date !== null && t.due_date !== undefined,
  );
  TestValidator.predicate(
    "due date analytics should show future tasks",
    dueTasks.length > 0,
  );

  // Step 6: Test search and filtering capabilities
  const searchQuery = "test search term";
  const searchResults = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        search: searchQuery,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(searchResults);

  TestValidator.predicate(
    "search results should return paginated structure",
    searchResults.pagination !== undefined && searchResults.data !== undefined,
  );

  // Step 7: Test status filtering
  const pendingTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        status: "pending",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(pendingTasks);

  TestValidator.equals(
    "pending status filter should return only pending tasks",
    pendingTasks.data.length > 0,
    true,
  );

  // Step 8: Test priority filtering
  const highPriorityTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        priority: "high",
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(highPriorityTasks);

  TestValidator.predicate(
    "high priority filter should return meaningful results",
    highPriorityTasks.data.length >= 0,
  );

  // Step 9: Test due date analytics
  const daysInFuture = 7;
  const futureDate = new Date(
    Date.now() + daysInFuture * 24 * 60 * 60 * 1000,
  ).toISOString();
  const upcomingTasks = await api.functional.todoApp.user.tasks.index(
    connection,
    {
      body: {
        due_before: futureDate,
      } satisfies ITodoAppTask.IRequest,
    },
  );
  typia.assert(upcomingTasks);

  TestValidator.predicate(
    "upcoming tasks should have due date analytics",
    upcomingTasks.data.length >= 0,
  );

  // Step 10: Test bulk operations with pagination
  const allTasks = await api.functional.todoApp.user.tasks.index(connection, {
    body: {
      page: 1,
      limit: 100,
    } satisfies ITodoAppTask.IRequest,
  });
  typia.assert(allTasks);

  TestValidator.predicate(
    "bulk task analytics should handle all results",
    allTasks.pagination.records === totalCount,
  );
  TestValidator.predicate(
    "all tasks pagination should return correct total",
    allTasks.data.length === totalCount,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test the complete user account deletion workflow where a user permanently
 * deletes their own account. Validates the soft deletion mechanism, session
 * invalidation, audit logging, and data preservation for compliance. Verifies
 * that users can only delete their own account with proper authentication
 * checks, password verification, and immediate feedback about deletion status.
 * Test includes token invalidation across all active sessions and ensures the
 * account is marked as inactive while maintaining referential integrity with
 * user-generated content like tasks and preferences.
 *
 * Step-by-step process:
 *
 * 1. Create a new user account to establish authentication context
 * 2. Create sample tasks to verify referential integrity during deletion
 * 3. Verify the user is authenticated and tokens are valid
 * 4. Delete the user account permanently
 * 5. Verify account deletion by checking deleted_at timestamp
 * 6. Test that the user can no longer authenticate or access resources
 */
export async function test_api_user_account_deletion_by_owner(
  connection: api.IConnection,
) {
  // Create a new user account to establish authentication context
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userData = {
    email: userEmail,
    password: "SecurePassword123!",
    name: RandomGenerator.name(),
    href: "https://example.com/todo-app",
    referrer: "https://example.com/signup",
  } satisfies ITodoAppUser.ICreate;

  const user: ITodoAppUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    { body: userData },
  );
  typia.assert(user);

  await TestValidator.predicate(
    "user account created successfully",
    user.id !== undefined,
  );
  await TestValidator.predicate(
    "user email matches registration",
    user.email === userEmail,
  );
  await TestValidator.predicate(
    "user status is active",
    user.status === "active",
  );
  await TestValidator.predicate(
    "deleted_at is null for active account",
    user.deleted_at === null || user.deleted_at === undefined,
  );

  // Create sample tasks to verify referential integrity during deletion
  const task1 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 8,
        }),
        status: "pending",
        description: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 4,
          wordMax: 7,
        }),
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(task1);

  const task2 = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 8,
        }),
        status: "completed",
        description: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 4,
          wordMax: 7,
        }),
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(task2);

  await TestValidator.predicate(
    "task1 belongs to user",
    task1.user.id === user.id,
  );
  await TestValidator.predicate(
    "task2 belongs to user",
    task2.user.id === user.id,
  );

  // Delete the user account permanently
  await api.functional.todoApp.user.users.erase(connection, {
    userId: user.id,
  });

  // Test that attempting to create tasks with deleted user fails
  await TestValidator.error(
    "user cannot create tasks after account deletion",
    async () => {
      await api.functional.todoApp.user.users.tasks.create(connection, {
        userId: user.id,
        body: {
          title: RandomGenerator.paragraph({
            sentences: 2,
            wordMin: 3,
            wordMax: 8,
          }),
          status: "pending",
        } satisfies ITodoAppTask.ICreate,
      });
    },
  );

  // Attempt to delete an already deleted account should fail
  await TestValidator.error(
    "cannot delete already deleted account",
    async () => {
      await api.functional.todoApp.user.users.erase(connection, {
        userId: user.id,
      });
    },
  );

  // Create a fresh, unauthenticated connection to test deletion effects
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // Test that unauthenticated access fails appropriately
  await TestValidator.error(
    "unauthenticated user cannot access protected resources",
    async () => {
      await api.functional.todoApp.user.users.erase(unauthConn, {
        userId: user.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSession";
import type { IRefreshToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefreshToken";
import type { ITodoAppSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSession";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test user session search and filtering functionality with basic criteria
 * including device type, validity status, and date ranges. Validates that users
 * can effectively query their own sessions for security monitoring and device
 * management. Checks that filtering correctly identifies active vs expired
 * sessions across different device types (web, mobile, tablet, api) with proper
 * pagination and result ordering.
 */
export async function test_api_user_session_search_basic_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create user account and establish authentication
  const userEmail = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: "TestPassword123!",
      name: RandomGenerator.name(),
      ip: null,
      href: "https://example.com/join",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // 2. Create additional session through refresh token
  const refreshResponse = await api.functional.auth.user.refresh(connection, {
    body: {
      refresh_token: user.token.refresh,
    } satisfies ITodoAppUser.IRefresh,
  });
  typia.assert(refreshResponse);

  // 3. Create a task to satisfy prerequisite
  const task = await api.functional.todoApp.user.users.tasks.create(
    connection,
    {
      userId: user.id,
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        status: "pending",
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(task);

  // 4. Test basic session search without filters
  const allSessions = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        page: {
          current: 0,
          limit: 20,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(allSessions);

  TestValidator.predicate("returns session list", allSessions.data.length > 0);
  TestValidator.equals(
    "contains current user",
    allSessions.data[0].user.id,
    user.id,
  );

  // Validate basic session structure
  TestValidator.predicate(
    "all sessions have valid structure",
    allSessions.data.every(
      (session) =>
        session.id &&
        session.user &&
        session.is_valid !== undefined &&
        session.created_at,
    ),
  );

  // 5. Test device type filtering - validate actual device types in results
  const webSessions = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        device_type: "web",
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(webSessions);

  TestValidator.predicate(
    "web device sessions filtered correctly",
    webSessions.data.length === 0 ||
      webSessions.data.every((s) => s.device_type === "web"),
  );

  // 6. Test validity status filtering with proper validation
  const validSessions = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        is_valid: true,
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(validSessions);

  TestValidator.predicate(
    "all returned sessions are valid",
    validSessions.data.every((session) => session.is_valid === true),
  );

  // 7. Test date range filtering with formal date handling
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const thirtyDaysFromNow = new Date(
    Date.now() + 30 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const recentSessions = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        created_after: oneDayAgo satisfies string & tags.Format<"date-time">,
        expired_before: thirtyDaysFromNow satisfies string &
          tags.Format<"date-time">,
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(recentSessions);

  TestValidator.predicate(
    "sessions found within date range",
    recentSessions.data.length > 0,
  );

  // 8. Test IP address pattern filtering
  const ipv4Sessions = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        ip: "192.168.1",
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(ipv4Sessions);

  TestValidator.predicate(
    "IP filtering returns sessions or empty results when no IP match",
    ipv4Sessions.data.length >= 0,
  );

  // 9. Test authentication context filtering
  const standardSessions =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userId: user.id,
      body: {
        session_type: "standard",
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    });
  typia.assert(standardSessions);

  TestValidator.predicate(
    "standard sessions found",
    standardSessions.data.length > 0,
  );
  TestValidator.predicate(
    "standard session type audit",
    standardSessions.data.length === 0 ||
      standardSessions.data.every((s) => s.session_type === "standard"),
  );

  // 10. Test pagination functionality with systematic verification
  const page1 = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        page: {
          current: 0,
          limit: 5,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(page1);

  const page2 = await api.functional.todoApp.user.users.sessions.index(
    connection,
    {
      userId: user.id,
      body: {
        page: {
          current: 1,
          limit: 5,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    },
  );
  typia.assert(page2);

  TestValidator.predicate(
    "pagination returns valid data",
    page1.data.length >= 0 && page2.data.length >= 0,
  );

  // Validate pagination info matches returned data
  TestValidator.equals(
    "page 1 data length does not exceed limit",
    Math.min(page1.data.length, 5),
    page1.data.length,
  );
  TestValidator.equals(
    "page 2 data length does not exceed limit",
    Math.min(page2.data.length, 5),
    page2.data.length,
  );

  // 11. Test combined filtering across multiple criteria
  const combinedFiltered =
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userId: user.id,
      body: {
        device_type: "web",
        is_valid: true,
        created_after: oneDayAgo satisfies string & tags.Format<"date-time">,
        session_type: "standard",
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    });
  typia.assert(combinedFiltered);

  TestValidator.predicate(
    "combined filters work",
    combinedFiltered.data.length >= 0,
  );

  if (combinedFiltered.data.length > 0) {
    TestValidator.predicate(
      "combined filter criteria satisfied",
      combinedFiltered.data.every(
        (session) =>
          session.device_type === "web" &&
          session.is_valid === true &&
          session.session_type === "standard" &&
          new Date(session.created_at) >= new Date(oneDayAgo),
      ),
    );
  }

  // 12. Verify security boundaries - user can only query own sessions
  const otherUser = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error("cannot query other user's sessions", async () => {
    await api.functional.todoApp.user.users.sessions.index(connection, {
      userId: otherUser,
      body: {
        page: {
          current: 0,
          limit: 10,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies ITodoAppSession.IRequest,
    });
  });

  return;
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
