  // Test 3: Create task with "low" priority
  const taskLowPriority = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskLowPriority);
  TestValidator.equals(
    "task with low priority",
    taskLowPriority.priority,
    "low",
  );

  // Test 4: Create task with "medium" priority (explicit)
  const taskMediumPriority = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskMediumPriority);
  TestValidator.equals(
    "task with medium priority",
    taskMediumPriority.priority,
    "medium",
  );

  // Test 5: Create task with "high" priority
  const taskHighPriority = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskHighPriority);
  TestValidator.equals(
    "task with high priority",
    taskHighPriority.priority,
    "high",
  );

  // Test 6: Create task with null priority (should default to medium)
  const taskNullPriority = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: null,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskNullPriority);
  TestValidator.equals(
    "task with null priority should default to medium",
    taskNullPriority.priority,
    "medium",
  );

  // Test 7: Create task with description and priority
  const taskWithDescription = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        description: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 4,
          wordMax: 8,
        }),
        status: "pending",
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskWithDescription);
  TestValidator.equals(
    "task with description has correct priority",
    taskWithDescription.priority,
    "high",
  );
  TestValidator.predicate(
    "task with description has description",
    !!taskWithDescription.description,
  );

  // Test 8: Create completed task with priority
  const taskCompleted = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "completed",
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskCompleted);
  TestValidator.equals(
    "completed task has correct priority",
    taskCompleted.priority,
    "low",
  );
  TestValidator.equals(
    "completed task has correct status",
    taskCompleted.status,
    "completed",
  );

  // Test 9: Create task with due date and priority
  const futureDate = new Date(Date.now() + 86400000).toISOString(); // Tomorrow
  const taskWithDueDate = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        status: "pending",
        priority: "medium",
        due_date: futureDate,
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(taskWithDueDate);
  TestValidator.equals(
    "task with due date has correct priority",
    taskWithDueDate.priority,
    "medium",
  );
  TestValidator.equals(
    "task with due date has correct due date",
    taskWithDueDate.due_date,
    futureDate,
  );

  // Test 10: Create multiple tasks and verify they all have priorities
  const taskBodies = ArrayUtil.repeat(5, (index) => ({
    title: RandomGenerator.paragraph({ sentences: 1, wordMin: 3, wordMax: 7 }),
    status: "pending" as const,
    priority: RandomGenerator.pick(["none", "low", "medium", "high"] as const),
  }));

  const tasks = await ArrayUtil.asyncMap(taskBodies, async (body) => {
    const task = await api.functional.todoApp.user.tasks.create(connection, {
      body,
    });
    typia.assert(task);
    return task;
  });

  TestValidator.predicate(
    "all created tasks have priorities",
    tasks.every((task) => !!task.priority),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

export async function test_api_task_creation_with_due_dates(
  connection: api.IConnection,
) {
  // Test 1: Create user account with proper authentication tracking
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "password123",
      name: RandomGenerator.name(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
      href: "https://example.com/todo",
      referrer: "https://example.com/signup",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Test 2: Create task with due date (tomorrow) - using proper date handling
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowsTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3, wordMax: 5 }),
        description: RandomGenerator.paragraph({ sentences: 5, wordMax: 10 }),
        status: "pending",
        priority: "high",
        due_date: tomorrow.toISOString(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(tomorrowsTask);
  TestValidator.predicate(
    "tomorrow's task has due date",
    tomorrowsTask.due_date !== null && tomorrowsTask.due_date !== undefined,
  );
  TestValidator.predicate(
    "tomorrow's task due date is within valid range",
    new Date(tomorrowsTask.due_date!).toDateString() ===
      tomorrow.toDateString(),
  );
  TestValidator.equals(
    "tomorrow's task status",
    tomorrowsTask.status,
    "pending",
  );
  TestValidator.equals(
    "tomorrow's task priority",
    tomorrowsTask.priority,
    "high",
  );

  // Test 3: Create task with future due date (30 days from now) - within 5 year limit
  const futureDate = new Date();
  futureDate.setDate(futureDate.getDate() + 30);
  const futureTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2, wordMax: 5 }),
        description: RandomGenerator.paragraph({ sentences: 4, wordMax: 10 }),
        status: "pending",
        priority: "medium",
        due_date: futureDate.toISOString(),
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(futureTask);
  TestValidator.predicate(
    "future task has due date",
    futureTask.due_date !== null && futureTask.due_date !== undefined,
  );
  TestValidator.predicate(
    "future task due date is within valid range",
    new Date(futureTask.due_date!).toDateString() === futureDate.toDateString(),
  );
  TestValidator.equals("future task status", futureTask.status, "pending");
  TestValidator.equals("future task priority", futureTask.priority, "medium");

  // Test 4: Create task without due date
  const noDueDateTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 4, wordMax: 5 }),
        description: RandomGenerator.paragraph({ sentences: 6, wordMax: 10 }),
        status: "pending",
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(noDueDateTask);
  TestValidator.predicate(
    "no due date task has null due_date",
    noDueDateTask.due_date === null,
  );
  TestValidator.equals(
    "no due date task status",
    noDueDateTask.status,
    "pending",
  );
  TestValidator.equals(
    "no due date task priority",
    noDueDateTask.priority,
    "low",
  );

  // Test 5: Create completed task (logical scenario - no future due date)
  const completedTask = await api.functional.todoApp.user.tasks.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2, wordMax: 5 }),
        description: RandomGenerator.paragraph({ sentences: 3, wordMax: 10 }),
        status: "completed",
        priority: "none",
      } satisfies ITodoAppTask.ICreate,
    },
  );
  typia.assert(completedTask);
  TestValidator.equals(
    "completed task status",
    completedTask.status,
    "completed",
  );
  TestValidator.predicate(
    "completed task has completed_at timestamp",
    completedTask.completed_at !== null &&
      completedTask.completed_at !== undefined,
  );
  TestValidator.predicate(
    "completed task has null due_date",
    completedTask.due_date === null,
  );

  // Test 6: Validate all tasks have correct user ownership
  TestValidator.equals(
    "tomorrow's task user ID",
    tomorrowsTask.user.id,
    user.id,
  );
  TestValidator.equals("future task user ID", futureTask.user.id, user.id);
  TestValidator.equals(
    "no due date task user ID",
    noDueDateTask.user.id,
    user.id,
  );
  TestValidator.equals(
    "completed task user ID",
    completedTask.user.id,
    user.id,
  );

  // Test 7: Validate proper metadata tracking
  TestValidator.predicate(
    "all tasks have creation timestamps",
    tomorrowsTask.created_at !== null && tomorrowsTask.created_at !== undefined,
  );
  TestValidator.predicate(
    "all tasks have update timestamps",
    tomorrowsTask.updated_at !== null && tomorrowsTask.updated_at !== undefined,
  );
  TestValidator.predicate(
    "all task titles are within length limit",
    tomorrowsTask.title.length <= 200 &&
      futureTask.title.length <= 200 &&
      noDueDateTask.title.length <= 200 &&
      completedTask.title.length <= 200,
  );

  // Test 8: Validate due date format (ISO 8601) for tasks with due dates
  if (tomorrowsTask.due_date && futureTask.due_date) {
    TestValidator.predicate(
      "tomorrow's task has valid ISO date format",
      /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/.test(
        tomorrowsTask.due_date,
      ),
    );
    TestValidator.predicate(
      "future task has valid ISO date format",
      /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])(T|\s)([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]{1,9})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/.test(
        futureTask.due_date,
      ),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import type { ITodoAppTaskMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskMetric";
import type { ITodoAppTaskStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskStatistics";
import type { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";

/**
 * Test task statistics endpoint with edge cases including empty task lists, all
 * completed tasks, all pending tasks, tasks with different priority
 * distributions, overdue tasks, and tasks due in different timeframes.
 * Validates that statistics calculation remains accurate and responsive even
 * with unusual data patterns, tests divide-by-zero scenarios (completion rate
 * when no tasks), and verifies proper handling of tasks with various due date
 * statuses (overdue, due today, due this week).
 */
export async function test_api_task_statistics_edge_cases(
  connection: api.IConnection,
) {
  // Step 1: Authenticate user to test statistics with edge case scenarios
  const email = typia.random<string & tags.Format<"email">>();
  const user = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password: "password123",
      href: "https://example.com",
      referrer: "https://example.com",
    } satisfies ITodoAppUser.ICreate,
  });
  typia.assert(user);

  // Step 2: Test empty task list statistics
  const emptyStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(emptyStats);

  TestValidator.equals(
    "empty task list total tasks count",
    emptyStats.total_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list active tasks count",
    emptyStats.active_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list completed tasks count",
    emptyStats.completed_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list pending tasks count",
    emptyStats.pending_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list completion rate when no tasks",
    emptyStats.completion_rate.value,
    0,
  );
  TestValidator.equals(
    "empty task list priority tasks all zero",
    emptyStats.high_priority_tasks.value +
      emptyStats.medium_priority_tasks.value +
      emptyStats.low_priority_tasks.value +
      emptyStats.no_priority_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list overdue tasks",
    emptyStats.overdue_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list due today tasks",
    emptyStats.due_today_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list due this week tasks",
    emptyStats.due_this_week_tasks.value,
    0,
  );
  TestValidator.equals(
    "empty task list average completion time",
    emptyStats.average_completion_time_days.value,
    0,
  );

  // Step 3: Create all completed tasks scenario
  const completedTasks = await ArrayUtil.asyncRepeat(5, async (index) =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: `Completed Task ${index + 1}`,
        status: "completed",
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  typia.assert(completedTasks);

  const allCompletedStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(allCompletedStats);

  TestValidator.equals(
    "all completed tasks total count",
    allCompletedStats.total_tasks.value,
    5,
  );
  TestValidator.equals(
    "all completed tasks completed count",
    allCompletedStats.completed_tasks.value,
    5,
  );
  TestValidator.equals(
    "all completed tasks pending count",
    allCompletedStats.pending_tasks.value,
    0,
  );
  TestValidator.equals(
    "all completed completion rate",
    allCompletedStats.completion_rate.value,
    1,
  );

  // Step 4: Create all pending tasks scenario
  const pendingTasks = await ArrayUtil.asyncRepeat(3, async (index) =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: `Pending Task ${index + 1}`,
        status: "pending",
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  typia.assert(pendingTasks);

  const mixedStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(mixedStats);

  TestValidator.equals(
    "mixed tasks total count",
    mixedStats.total_tasks.value,
    8,
  ); // 5 completed + 3 pending
  TestValidator.equals(
    "mixed tasks completed count",
    mixedStats.completed_tasks.value,
    5,
  );
  TestValidator.equals(
    "mixed tasks pending count",
    mixedStats.pending_tasks.value,
    3,
  );
  TestValidator.equals(
    "mixed tasks completion rate",
    mixedStats.completion_rate.value,
    5 / 8,
  );

  // Step 5: Test priority distribution
  const priorityTasks = await ArrayUtil.asyncRepeat(2, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "High Priority Task",
        status: "pending",
        priority: "high",
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  await ArrayUtil.asyncRepeat(3, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "Medium Priority Task",
        status: "pending",
        priority: "medium",
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  await ArrayUtil.asyncRepeat(1, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "Low Priority Task",
        status: "pending",
        priority: "low",
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  await ArrayUtil.asyncRepeat(1, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "No Priority Task",
        status: "pending",
        priority: null,
      } satisfies ITodoAppTask.ICreate,
    }),
  );

  const priorityStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(priorityStats);

  TestValidator.equals(
    "priority distribution high",
    priorityStats.high_priority_tasks.value,
    2,
  );
  TestValidator.equals(
    "priority distribution medium",
    priorityStats.medium_priority_tasks.value,
    3,
  );
  TestValidator.equals(
    "priority distribution low",
    priorityStats.low_priority_tasks.value,
    1,
  );
  TestValidator.equals(
    "priority distribution none",
    priorityStats.no_priority_tasks.value,
    3,
  ); // plus the original pending tasks

  // Step 6: Test overdue tasks
  const now = new Date();
  const overdueTasks = await ArrayUtil.asyncRepeat(2, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "Overdue Task",
        status: "pending",
        due_date: new Date(
          now.getTime() - 7 * 24 * 60 * 60 * 1000,
        ).toISOString(), // 1 week ago
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  typia.assert(overdueTasks);

  const overdueStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(overdueStats);

  TestValidator.predicate(
    "overdue tasks count increased",
    overdueStats.overdue_tasks.value >= 2,
  );

  // Step 7: Test tasks due today
  const dueTodayTasks = await ArrayUtil.asyncRepeat(1, async () =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: "Due Today Task",
        status: "pending",
        due_date: now.toISOString(), // Today
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  typia.assert(dueTodayTasks);

  const dueTodayStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(dueTodayStats);

  TestValidator.predicate(
    "due today tasks count",
    dueTodayStats.due_today_tasks.value >= 1,
  );

  // Step 8: Test tasks due this week
  const dueThisWeekTasks = await ArrayUtil.asyncRepeat(3, async (index) =>
    api.functional.todoApp.user.tasks.create(connection, {
      body: {
        title: `Due This Week Task ${index + 1}`,
        status: "pending",
        due_date: new Date(
          now.getTime() + (index + 1) * 24 * 60 * 60 * 1000,
        ).toISOString(), // Tomorrow, 2 days, 3 days
      } satisfies ITodoAppTask.ICreate,
    }),
  );
  typia.assert(dueThisWeekTasks);

  const dueThisWeekStats =
    await api.functional.todoApp.user.tasks.statistics.at(connection);
  typia.assert(dueThisWeekStats);

  TestValidator.predicate(
    "due this week tasks count",
    dueThisWeekStats.due_this_week_tasks.value >= 3,
  );

  // Step 9: Test numerical edge cases in metrics
  TestValidator.predicate(
    "all metric values are non-negative integers",
    Object.values(overdueStats).every(
      (metric: ITodoAppTaskMetric) =>
        metric.value >= 0 && Number.isInteger(metric.value),
    ),
  );

  TestValidator.predicate(
    "completion rate is between 0 and 1 inclusive",
    overdueStats.completion_rate.value >= 0 &&
      overdueStats.completion_rate.value <= 1,
  );

  TestValidator.predicate(
    "total tasks equals sum of pending and completed",
    overdueStats.total_tasks.value ===
      overdueStats.pending_tasks.value + overdueStats.completed_tasks.value,
  );

  TestValidator.predicate(
    "average completion time is non-negative",
    overdueStats.average_completion_time_days.value >= 0,
  );

  // Step 10: Test monthly activity metrics
  TestValidator.predicate(
    "tasks created this month is non-negative",
    overdueStats.tasks_created_this_month.value >= 0,
  );

  TestValidator.predicate(
    "tasks completed this month is non-negative",
    overdueStats.tasks_completed_this_month.value >= 0,
  );
}

