import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTaskStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskStatistics";
import { ITodoAppTaskMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTaskMetric";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function getTodoAppUserTasksStatistics(props: {
  user: UserPayload;
}): Promise<ITodoAppTaskStatistics> {
  // Get current date for comparison
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const nextWeek = new Date(today);
  nextWeek.setDate(today.getDate() + 7);
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

  // Get all tasks for the user (including deleted for total count)
  const allTasks = await MyGlobal.prisma.todo_app_tasks.findMany({
    where: {
      todo_app_user_id: props.user.id,
    },
    select: {
      status: true,
      priority: true,
      due_date: true,
      created_at: true,
      completed_at: true,
      deleted_at: true,
    },
  });

  const activeTasks = allTasks.filter((task) => task.deleted_at === null);

  // Calculate all statistics from the data
  const totalTasksCount = allTasks.length;
  const activeTasksCount = activeTasks.length;
  const pendingTasksCount = activeTasks.filter(
    (task) => task.status === "pending",
  ).length;
  const completedTasksCount = activeTasks.filter(
    (task) => task.status === "completed",
  ).length;

  // Calculate completion rate
  const completionRate =
    activeTasksCount > 0 ? completedTasksCount / activeTasksCount : 0;

  // Count by priority
  const highPriorityCount = activeTasks.filter(
    (task) => task.priority === "high",
  ).length;
  const mediumPriorityCount = activeTasks.filter(
    (task) => task.priority === "medium",
  ).length;
  const lowPriorityCount = activeTasks.filter(
    (task) => task.priority === "low",
  ).length;
  const noPriorityCount = activeTasks.filter(
    (task) => task.priority === null,
  ).length;

  // Count overdue and due-date related
  const overdueTasksCount = activeTasks.filter(
    (task) =>
      task.status === "pending" &&
      task.due_date !== null &&
      new Date(task.due_date) < now,
  ).length;

  const dueTodayCount = activeTasks.filter((task) => {
    if (task.status !== "pending" || !task.due_date) return false;
    const dueDate = new Date(task.due_date);
    return (
      dueDate >= today &&
      dueDate < new Date(today.getTime() + 24 * 60 * 60 * 1000)
    );
  }).length;

  const dueThisWeekCount = activeTasks.filter((task) => {
    if (task.status !== "pending" || !task.due_date) return false;
    const dueDate = new Date(task.due_date);
    return dueDate >= today && dueDate < nextWeek;
  }).length;

  // Monthly activity
  const tasksCreatedThisMonthCount = activeTasks.filter(
    (task) => new Date(task.created_at) >= startOfMonth,
  ).length;

  const tasksCompletedThisMonthCount = activeTasks.filter(
    (task) =>
      task.status === "completed" &&
      task.completed_at !== null &&
      new Date(task.completed_at) >= startOfMonth,
  ).length;

  // Calculate average completion time
  const completedTasks = activeTasks.filter(
    (task) => task.status === "completed" && task.completed_at !== null,
  );

  let averageCompletionTime = 0;
  if (completedTasks.length > 0) {
    const totalDays = completedTasks.reduce((sum, task) => {
      const diffMs =
        new Date(task.completed_at!).getTime() -
        new Date(task.created_at).getTime();
      const diffDays = diffMs / (1000 * 60 * 60 * 24);
      return sum + diffDays;
    }, 0);

    averageCompletionTime = totalDays / completedTasks.length;
  }

  // Helper function to ensure proper int32 typing
  const toMetricValue = (
    value: number,
  ): number & tags.Type<"int32"> & tags.Minimum<0> => {
    const intValue = Math.floor(value);
    return typia.assert<number & tags.Type<"int32"> & tags.Minimum<0>>(
      intValue >= 0 ? intValue : 0,
    );
  };

  return {
    total_tasks: {
      value: toMetricValue(totalTasksCount),
    },
    active_tasks: {
      value: toMetricValue(activeTasksCount),
    },
    pending_tasks: {
      value: toMetricValue(pendingTasksCount),
    },
    completed_tasks: {
      value: toMetricValue(completedTasksCount),
    },
    completion_rate: {
      value: toMetricValue(completionRate * 100),
    },
    high_priority_tasks: {
      value: toMetricValue(highPriorityCount),
    },
    medium_priority_tasks: {
      value: toMetricValue(mediumPriorityCount),
    },
    low_priority_tasks: {
      value: toMetricValue(lowPriorityCount),
    },
    no_priority_tasks: {
      value: toMetricValue(noPriorityCount),
    },
    overdue_tasks: {
      value: toMetricValue(overdueTasksCount),
    },
    due_today_tasks: {
      value: toMetricValue(dueTodayCount),
    },
    due_this_week_tasks: {
      value: toMetricValue(dueThisWeekCount),
    },
    tasks_created_this_month: {
      value: toMetricValue(tasksCreatedThisMonthCount),
    },
    tasks_completed_this_month: {
      value: toMetricValue(tasksCompletedThisMonthCount),
    },
    average_completion_time_days: {
      value: toMetricValue(averageCompletionTime),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoAppUser.ICreate;
}): Promise<ITodoAppUser.IAuthorized> {
  // Check for duplicate email
  const existing = await MyGlobal.prisma.todo_app_users.findFirst({
    where: { email: props.body.email },
  });

  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Create user record
  const user = await MyGlobal.prisma.todo_app_users.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      email: props.body.email,
      password_hash: hashedPassword,
      name: props.body.name ?? null,
      status: "active",
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Calculate token expiration times
  const now = new Date();
  const accessExpires = toISOStringSafe(
    new Date(now.getTime() + 60 * 60 * 1000),
  ); // 1 hour
  const refreshExpires = toISOStringSafe(
    new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
  ); // 7 days

  // Create session record
  const session = await MyGlobal.prisma.todo_app_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_user_id: user.id,
      ip: props.body.ip ?? "0.0.0.0",
      href: props.body.href,
      referrer: props.body.referrer,
      device_type: null,
      device_name: null,
      is_valid: true,
      session_type: "standard",
      created_at: toISOStringSafe(now),
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens
  const tokenPayload = {
    type: "user",
    id: user.id,
    session_id: session.id,
    created_at: toISOStringSafe(now),
  } as const;

  const accessToken = jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
    expiresIn: "1h",
    issuer: "autobe",
  });

  const refreshToken = jwt.sign(
    { ...tokenPayload, tokenType: "refresh" as const },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  return {
    id: user.id,
    email: user.email,
    name: user.name ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at === null ? undefined : toISOStringSafe(user.deleted_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IEmailAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IEmailAddress";
import { IPassword } from "@ORGANIZATION/PROJECT-api/lib/structures/IPassword";
import { IIPAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IIPAddress";
import { IURI } from "@ORGANIZATION/PROJECT-api/lib/structures/IURI";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserLogin(props: {
  body: ITodoAppUser.ILogin;
}): Promise<ITodoAppUser.IAuthorized> {
  // Validate user credentials - find user by email
  const user = await MyGlobal.prisma.todo_app_users.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });

  if (!user) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Verify password using PasswordUtil
  const isValid = await PasswordUtil.verify(
    props.body.password,
    user.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Check account status - must be active
  if (user.status !== "active") {
    throw new HttpException("Account is not active", 403);
  }

  // Create new session for this login
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const session = await MyGlobal.prisma.todo_app_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      todo_app_user_id: user.id,
      ip: props.body.ip ?? "unknown",
      href: props.body.href,
      referrer: props.body.referrer,
      device_type: "web",
      is_valid: true,
      session_type: "standard",
      created_at: now,
      expired_at: accessExpires,
    },
  });

  // Generate JWT tokens
  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  return {
    id: user.id,
    email: user.email,
    name: user.name ?? null,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at: user.deleted_at ? toISOStringSafe(user.deleted_at) : null,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoAppUserUsersUserIdTasksTaskId(props: {
  user: UserPayload;
  userId: string & tags.Format<"uuid">;
  taskId: string & tags.Format<"uuid">;
  body: ITodoAppTask.IUpdate;
}): Promise<ITodoAppTask> {
  // Verify user authorization
  if (props.user.id !== props.userId) {
    throw new HttpException("You can only update your own tasks", 403);
  }

  // Check if task exists and belongs to user
  const existingTask = await MyGlobal.prisma.todo_app_tasks.findUnique({
    where: {
      id: props.taskId,
      deleted_at: null, // Only consider non-deleted tasks
    },
  });

  if (!existingTask) {
    throw new HttpException("Task not found", 404);
  }

  if (existingTask.todo_app_user_id !== props.userId) {
    throw new HttpException("Task not found", 404); // Don't reveal it exists but belongs to different user
  }

  // Build update data
  const updateData: Prisma.todo_app_tasksUpdateInput = {
    updated_at: new Date(),
  };

  // Handle optional fields - only update if provided
  if (props.body.title !== undefined) {
    updateData.title = props.body.title ?? undefined;
  }

  if (props.body.description !== undefined) {
    updateData.description = props.body.description;
  }

  if (props.body.status !== undefined) {
    updateData.status = props.body.status ?? undefined;

    // Handle completion timestamp
    if (
      props.body.status === "completed" &&
      existingTask.status !== "completed"
    ) {
      updateData.completed_at = new Date();
    } else if (props.body.status === "pending") {
      updateData.completed_at = null; // Reset completion when back to pending
    }
  }

  if (props.body.priority !== undefined) {
    updateData.priority = props.body.priority;
  }

  if (props.body.due_date !== undefined) {
    updateData.due_date = props.body.due_date
      ? new Date(props.body.due_date)
      : null;
  }

  // Update the task
  const updatedTask = await MyGlobal.prisma.todo_app_tasks.update({
    where: { id: props.taskId },
    data: updateData,
    include: {
      user: true, // Include user information for response
    },
  });

  // Get user data for summary
  const userSummary: ITodoAppUser.ISummary = {
    id: updatedTask.user.id,
    email: updatedTask.user.email,
    name: updatedTask.user.name,
    status: updatedTask.user.status,
    created_at: toISOStringSafe(updatedTask.user.created_at),
  };

  // Return the complete task object
  return {
    id: updatedTask.id,
    title: updatedTask.title,
    description: updatedTask.description,
    status: updatedTask.status,
    priority: updatedTask.priority,
    due_date: updatedTask.due_date
      ? toISOStringSafe(updatedTask.due_date)
      : undefined,
    completed_at: updatedTask.completed_at
      ? toISOStringSafe(updatedTask.completed_at)
      : undefined,
    created_at: toISOStringSafe(updatedTask.created_at),
    updated_at: toISOStringSafe(updatedTask.updated_at),
    deleted_at: updatedTask.deleted_at
      ? toISOStringSafe(updatedTask.deleted_at)
      : undefined,
    user: userSummary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTask } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTask";
import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserTasksBulk(props: {
  user: UserPayload;
  body: ITodoAppTask.IBulkRequest;
}): Promise<ITodoAppTask.IBulkResponse> {
  // Load all requested tasks with user information in single query
  const originalTasks = await MyGlobal.prisma.todo_app_tasks.findMany({
    where: {
      id: { in: props.body.task_ids },
      todo_app_user_id: props.user.id,
      deleted_at: null,
    },
    include: {
      // Remove todo_app_user include - not valid in this Prisma model
    },
  });

  // Check if all tasks exist and belong to user
  if (originalTasks.length !== props.body.task_ids.length) {
    throw new HttpException(
      "Some tasks do not exist or do not belong to the authenticated user",
      404,
    );
  }

  // Filter by status if requested, but keep track for non-matching tasks
  let tasksToProcess = originalTasks;
  const skippedTasks = new Set<string>();

  if (props.body.filter_status && props.body.filter_status !== "all") {
    tasksToProcess = originalTasks.filter((task) => {
      const matchesFilter = task.status === props.body.filter_status;
      if (!matchesFilter) {
        skippedTasks.add(task.id);
      }
      return matchesFilter;
    });
  }

  const results: ITodoAppTask.IBulkResult[] = [];
  let successCount = 0;
  let failureCount = 0;
  let warningCount = 0;
  const processedTasks = new Map<string, (typeof originalTasks)[0]>();

  // Process each task based on action type
  for (const task of originalTasks) {
    // Handle filtered tasks
    if (skippedTasks.has(task.id)) {
      results.push({
        task_id: task.id,
        status: "warning",
        error_message: `Task filtered out by status filter: ${props.body.filter_status}`,
        task: formatTaskResponse(task),
        operation_type: props.body.action,
      });
      warningCount++;
      continue;
    }

    try {
      let updateData: Record<string, unknown> = {};
      let warningMessage: string | null = null;
      let isSuccess = false;

      switch (props.body.action) {
        case "complete":
          if (task.status === "completed") {
            warningMessage = "Task was already completed";
          } else {
            updateData = {
              status: "completed",
              completed_at: new Date(),
            };
            isSuccess = true;
          }
          break;

        case "restore":
          if (task.status === "pending") {
            warningMessage = "Task was already pending";
          } else {
            updateData = {
              status: "pending",
              completed_at: null,
            };
            isSuccess = true;
          }
          break;

        case "update_priority":
          if (
            !props.body.parameters ||
            !("priority" in props.body.parameters)
          ) {
            throw new HttpException(
              "Priority parameter is required for update_priority action",
              400,
            );
          }
          updateData = {
            priority: props.body.parameters.priority,
          };
          isSuccess = true;
          break;

        case "update_due_date":
          if (
            !props.body.parameters ||
            !("due_date" in props.body.parameters)
          ) {
            throw new HttpException(
              "Due date parameter is required for update_due_date action",
              400,
            );
          }
          updateData = {
            due_date: props.body.parameters.due_date,
          };
          isSuccess = true;
          break;

        case "archive":
          if (task.deleted_at !== null) {
            warningMessage = "Task was already archived";
          } else {
            updateData = {
              deleted_at: new Date(),
            };
            isSuccess = true;
          }
          break;

        default:
          throw new HttpException(
            `Unknown bulk action: ${props.body.action}`,
            400,
          );
      }

      if (Object.keys(updateData).length > 0) {
        updateData.updated_at = new Date();
        const updated = await MyGlobal.prisma.todo_app_tasks.update({
          where: { id: task.id },
          data: updateData,
        });
        processedTasks.set(task.id, { ...task, ...updated });
        if (isSuccess) successCount++;
      } else {
        processedTasks.set(task.id, task);
        if (warningMessage) warningCount++;
      }

      results.push({
        task_id: task.id,
        status: warningMessage ? "warning" : "success",
        error_message: warningMessage,
        task: formatTaskResponse(processedTasks.get(task.id)!),
        operation_type: props.body.action,
      });
    } catch (error) {
      failureCount++;
      results.push({
        task_id: task.id,
        status: "failure",
        error_message:
          error instanceof Error ? error.message : "Unknown error occurred",
        task: formatTaskResponse(task),
        operation_type: props.body.action,
      });
    }
  }

  return {
    success_count: successCount,
    failure_count: failureCount,
    warning_count: warningCount,
    total_count: originalTasks.length,
    results,
    has_errors: failureCount > 0,
  };
}

/** Helper function to format task response with proper type safety */
function formatTaskResponse(task: any): ITodoAppTask {
  return {
    id: task.id,
    title: task.title,
    description: task.description,
    status: task.status,
    priority: task.priority,
    due_date: task.due_date
      ? toISOStringSafe(new Date(task.due_date))
      : task.due_date,
    created_at: toISOStringSafe(new Date(task.created_at)),
    updated_at: toISOStringSafe(new Date(task.updated_at)),
    deleted_at: task.deleted_at
      ? toISOStringSafe(new Date(task.deleted_at))
      : task.deleted_at,
    completed_at: task.completed_at
      ? toISOStringSafe(new Date(task.completed_at))
      : task.completed_at,
    user: {
      id: task.todo_app_user_id,
      email: task.todo_app_user?.email || "",
      name: task.todo_app_user?.name,
      status: task.todo_app_user?.status || "active",
      created_at: toISOStringSafe(
        new Date(task.todo_app_user?.created_at || task.created_at),
      ),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUser";
import { IRefreshToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IRefreshToken";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postAuthUserRefresh(props: {
  user: UserPayload;
  body: ITodoAppUser.IRefresh;
}): Promise<ITodoAppUser.IAuthorized> {
  // Verify the refresh token
  let decoded: {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "user";
  };

  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string & tags.Format<"uuid">;
      session_id: string & tags.Format<"uuid">;
      type: "user";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate token type matches expected actor
  if (decoded.type !== "user") {
    throw new HttpException("Invalid token type", 403);
  }

  // Validate session matches the authenticated user
  if (
    decoded.session_id !== props.user.session_id ||
    decoded.id !== props.user.id
  ) {
    throw new HttpException("Token session mismatch", 401);
  }

  // Get user data and validate account status
  const user = await MyGlobal.prisma.todo_app_users.findUnique({
    where: { id: props.user.id },
  });

  if (!user) {
    throw new HttpException("User not found", 404);
  }

  if (user.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  if (user.status !== "active") {
    throw new HttpException("Account is not active", 403);
  }

  // Generate new tokens with updated expiration
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const accessToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: props.user.session_id, // Maintain same session
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: props.user.session_id, // Maintain same session
      tokenType: "refresh",
      created_at: new Date().toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  // Return IAuthorized response
  return {
    id: user.id,
    email: user.email,
    name: user.name ?? undefined,
    status: user.status,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    deleted_at:
      user.deleted_at === null ? undefined : toISOStringSafe(user.deleted_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

