    ...((props.body.expired_after !== undefined ||
      props.body.expired_before !== undefined) && {
      expired_at: {
        ...(props.body.expired_after !== undefined && {
          gte: props.body.expired_after,
        }),
        ...(props.body.expired_before !== undefined && {
          lte: props.body.expired_before,
